  function startDrawerWatcher() {
    let timer = 0;
    new MutationObserver(() => {
      clearTimeout(timer);
      timer = setTimeout(() => {
        handleDrawerState();
        ensurePageToyCopywritingButton();
        observeManualTabRead();
        scheduleProjectListPrefetch();
        positionLauncher(document.getElementById(LAUNCHER_ID));
      }, 120);
    }).observe(document.body, { childList: true, subtree: true });
  }

  function handleUserDrawerTabClick(event) {
    if (!event || !event.isTrusted || !(event.target instanceof Element)) return;
    const detailButton = event.target.closest('button, a, [role="button"]');
    const projectRow = detailButton && detailButton.closest('tr');
    if (
      detailButton && projectRow &&
      !detailButton.closest('#' + PANEL_ID + ', .ant-drawer-open, .ant-drawer') &&
      /\/projectManagementChemicalNew/.test(location.pathname) &&
      compactText(detailButton.innerText || detailButton.textContent) === '\u8be6\u60c5'
    ) {
      const sku = findProjectSkuForActionRow(projectRow);
      if (sku) showProjectDetailOpeningFeedback(sku, loadData(sku) || { sku });
      return;
    }
    const tab = event.target.closest('[role="tab"], .ant-tabs-tab');
    if (!tab) return;
    const drawer = tab.closest('.ant-drawer-open, .ant-drawer');
    if (!drawer || drawer !== getProjectDrawer()) return;
    if (state.scanRunning) {
      const partial = state.scanData && state.scanData.sku ? state.scanData : null;
      stopScan();
      if (partial) {
        saveData(partial.sku, partial);
        if (state.selectedSku === partial.sku) state.data = normalizeData(loadData(partial.sku) || partial);
      }
    }
    if (state.drawerTabFlowRunning || state.drawerTabFlowTimer) {
      state.drawerTabFlowUserInterrupted = true;
      cancelDrawerTabFlow({ preserveUserInterrupted: true });
    }
    const sku = getProjectDrawerHeaderSku(drawer);
    const tabName = compactText(tab.innerText || tab.textContent || '');
    if (sku && tabName) {
      state.observedDrawer = drawer;
      state.observedSku = sku;
      state.observedTab = tabName;
      stopManualTabRead();
      state.manualCollectTimer = window.setTimeout(() => readCurrentManualTab(drawer, sku, tabName), 420);
    }
  }

  function findProjectSkuForActionRow(row) {
    if (!row) return '';
    const directSku = findSku(getVisibleText(row));
    if (directSku) return directSku;
    const rowId = row.getAttribute('rowid');
    if (!rowId) return '';
    const linkedRow = Array.from(document.querySelectorAll('tr[rowid="' + cssEscape(rowId) + '"]'))
      .find((candidate) => candidate !== row && findSku(getVisibleText(candidate)));
    return linkedRow ? findSku(getVisibleText(linkedRow)) : '';
  }

  function showProjectDetailOpeningFeedback(sku, data) {
    if (!sku) return;
    state.openingProjectDetail = true;
    state.openingProjectDetailSku = sku;
    state.view = 'detail';
    state.selectedSku = sku;
    state.data = normalizeData(data || { sku });
    resetExcelState();
    lockLoadingTip(sku);
    expandPanel();
    renderShell(L.openingDetail);
    window.setTimeout(() => {
      if (!state.openingProjectDetail || state.openingProjectDetailSku !== sku) return;
      state.openingProjectDetail = false;
      state.openingProjectDetailSku = '';
      renderShell();
    }, 7000);
  }

  function cancelDrawerTabFlow(options) {
    const preserveUserInterrupted = Boolean(options && options.preserveUserInterrupted);
    clearScanLoadingTipTimer();
    if (state.drawerTabFlowTimer) window.clearTimeout(state.drawerTabFlowTimer);
    state.drawerTabFlowTimer = 0;
    state.drawerTabFlowToken += 1;
    state.drawerTabFlowRunning = false;
    state.drawerTabFlowSku = '';
    state.drawerTabFlowDrawer = null;
    if (!preserveUserInterrupted) state.drawerTabFlowUserInterrupted = false;
  }

  function beginForegroundDrawerTabFlow(sku, drawer) {
    cancelDrawerTabFlow();
    const token = state.drawerTabFlowToken + 1;
    state.drawerTabFlowToken = token;
    state.drawerTabFlowRunning = true;
    state.drawerTabFlowSku = String(sku || '');
    state.drawerTabFlowDrawer = drawer || null;
    state.drawerTabFlowUserInterrupted = false;
    return token;
  }

  function finishForegroundDrawerTabFlow(token) {
    if (state.drawerTabFlowToken !== token) return;
    state.drawerTabFlowRunning = false;
    state.drawerTabFlowSku = '';
    state.drawerTabFlowDrawer = null;
  }

  function scheduleProjectListPrefetch() {
    if (!state.settings.collectionEnabled || !/\/projectManagementChemicalNew/.test(location.pathname)) return;
    window.clearTimeout(state.projectListPrefetchTimer);
    state.projectListPrefetchTimer = window.setTimeout(prefetchProjectAllListData, 360);
  }

  function prefetchProjectAllListData() {
    state.projectListPrefetchTimer = 0;
    const activeWorkflowTab = getActiveProjectWorkflowTabText();
    if (!state.settings.collectionEnabled || !/^(?:\u5168\u90e8|\u8bbe\u8ba1\u4efb\u52a1)/.test(activeWorkflowTab)) return;
    const rows = collectProjectAllListRows();
    if (!rows.length) return;
    const signature = activeWorkflowTab + '|' + JSON.stringify(rows);
    if (signature === state.projectListPrefetchSignature) return;
    state.projectListPrefetchSignature = signature;
    return syncProjectListRowsToCache(rows, {
      source: 'project-all',
      ledgerLog: '\u6574\u9875\u8bbe\u8ba1\u5206\u914d\u4efb\u52a1\u5df2\u540c\u6b65\u5230\u4eca\u65e5\u5de5\u4f5c\u53f0',
      cacheLog: '\u65b0\u54c1\u5f00\u53d1\u5217\u8868\u57fa\u7840\u4fe1\u606f\u5df2\u9759\u9ed8\u7f13\u5b58',
    });
  }

  function syncProjectListRowsToCache(rows, options) {
    const opts = options || {};
    const source = String(opts.source || 'project-all');
    const list = (Array.isArray(rows) ? rows : []).filter((row) => row && row.sku);
    if (!list.length) return { fetchedCount: 0, changedCount: 0, addedCount: 0, ledgerChangedCount: 0, ledgerAddedCount: 0 };
    let changedCount = 0;
    let addedCount = 0;
    let ledgerChangedCount = 0;
    let ledgerAddedCount = 0;
    let ledgerEligibleCount = 0;
    syncDailyLedgerBeforeMutation();
    list.forEach((row) => {
      const previous = normalizeData(loadData(row.sku) || { sku: row.sku });
      const rowName = normalizeProductNameValue(row.name);
      const previousName = normalizeProductNameValue(previous.name);
      const benchmarkImageUrl = stripOssResizeParams(row.benchmarkImageUrl || '');
      const productListImageUrl = stripOssResizeParams(row.productListImageUrl || '');
      const preserveEffectImage = previous.skuImageSource === 'effectImage' && Boolean(previous.skuImageUrl || previous.skuImageFallbackUrl);
      const useProductListAsSkuImage = row.projectStatus === '\u5df2\u5b8c\u6210' && Boolean(productListImageUrl || row.productListImageUrl) && !preserveEffectImage;
      const candidate = normalizeData({
        ...previous,
        sku: row.sku,
        brand: row.brand || previous.brand || '',
        name: rowName || previousName || '',
        projectRowId: row.rowId || previous.projectRowId || '',
        projectId: row.projectId || previous.projectId || '',
        productId: row.productId || previous.productId || '',
        productVersionId: row.productVersionId || previous.productVersionId || '',
        developerName: row.developerName || previous.developerName || '',
        developerText: row.developerText || previous.developerText || '',
        benchmarkImageUrl: benchmarkImageUrl || previous.benchmarkImageUrl || '',
        benchmarkImageFallbackUrl: row.benchmarkImageUrl || previous.benchmarkImageFallbackUrl || benchmarkImageUrl || '',
        referenceUrl: row.referenceUrl || previous.referenceUrl || '',
        developmentAdvice: row.developmentAdvice || previous.developmentAdvice || '',
        artPriority: row.artPriority || previous.artPriority || '',
        projectStatus: row.projectStatus || previous.projectStatus || '',
        designType: row.designType || previous.designType || '',
        specificationText: row.specificationText || previous.specificationText || '',
        productListImageUrl: productListImageUrl || previous.productListImageUrl || '',
        productListImageFallbackUrl: row.productListImageUrl || previous.productListImageFallbackUrl || productListImageUrl || '',
        designAssignedAt: row.designAssignedAt || previous.designAssignedAt || '',
        developmentAssignedAt: row.developmentAssignedAt || previous.developmentAssignedAt || '',
        projectCreatedAt: row.projectCreatedAt || previous.projectCreatedAt || '',
        departmentName: row.departmentName || previous.departmentName || '',
        projectOwnerName: row.projectOwnerName || previous.projectOwnerName || '',
        promotionStatus: row.promotionStatus || previous.promotionStatus || '',
        listingStatus: row.listingStatus || previous.listingStatus || '',
        bomStatus: row.bomStatus || previous.bomStatus || '',
        requiresPlanStock: row.requiresPlanStock || previous.requiresPlanStock || '',
        bomAuditStatus: row.bomAuditStatus || previous.bomAuditStatus || '',
        plmCategory: row.plmCategory || previous.plmCategory || '',
        productType: row.productType || previous.productType || '',
        productTypeValue: row.productTypeValue || previous.productTypeValue || '',
        skuImageUrl: useProductListAsSkuImage ? (productListImageUrl || row.productListImageUrl) : (previous.skuImageUrl || ''),
        skuImageFallbackUrl: useProductListAsSkuImage ? (row.productListImageUrl || productListImageUrl) : (previous.skuImageFallbackUrl || ''),
        skuImageSource: useProductListAsSkuImage ? 'productListImage' : (previous.skuImageSource || ''),
        listPrefetchSource: previous.listPrefetchSource || source,
      });
      const assignedDate = parseLedgerDateFromText(row.designAssignedAt);
      if (assignedDate) {
        ledgerEligibleCount += 1;
        const assignedMonth = getMonthKeyFromDateKey(assignedDate);
        const existingLedger = (state.ledgerRecords || []).find((item) => item.sku === row.sku && getMonthKeyFromDateKey(item.date) === assignedMonth);
        const syncedLedger = upsertDailyLedgerFromData(candidate, {
          deferSave: true,
          skipStorageSync: true,
          skipUnchanged: true,
          note: existingLedger ? undefined : (opts.ledgerNote || '\u6574\u9875\u5217\u8868\u81ea\u52a8\u52a0\u5165'),
        });
        if (syncedLedger && syncedLedger !== existingLedger) {
          ledgerChangedCount += 1;
          if (!existingLedger) ledgerAddedCount += 1;
        }
      }
      const dataChanged = hasMeaningfulDataChange(previous, candidate);
      const indexMissing = !state.index.some((item) => item && item.sku === row.sku);
      if (indexMissing) addedCount += 1;
      if (!dataChanged && !indexMissing) return;
      const saved = dataChanged ? normalizeData({
        ...candidate,
        listPrefetchedAt: new Date().toLocaleString(),
        updatedAt: new Date().toLocaleString(),
        updatedAtMs: Date.now(),
      }) : candidate;
      if (dataChanged) saveDataDirect(row.sku, saved);
      upsertIndex(saved);
      if (state.data && state.data.sku === row.sku) state.data = saved;
      changedCount += 1;
    });
    if (ledgerChangedCount) {
      saveDailyLedger();
      if (opts.ledgerLog !== false) addLog('info', opts.ledgerLog || '\u8bbe\u8ba1\u5206\u914d\u4efb\u52a1\u5df2\u540c\u6b65\u5230\u4eca\u65e5\u5de5\u4f5c\u53f0', ledgerChangedCount + '/' + ledgerEligibleCount + '\u4e2a\u7f16\u7801');
    }
    if (!changedCount && !ledgerChangedCount) return { fetchedCount: list.length, changedCount, addedCount, ledgerChangedCount, ledgerAddedCount };
    if (changedCount) {
      queueCloudBackup();
      if (opts.cacheLog !== false) addLog('info', opts.cacheLog || '\u65b0\u54c1\u5f00\u53d1\u5217\u8868\u57fa\u7840\u4fe1\u606f\u5df2\u9759\u9ed8\u7f13\u5b58', changedCount + '/' + list.length + '\u4e2a\u7f16\u7801');
    }
    if (opts.render !== false && (state.view === 'home' || state.view === 'detail' || state.view === 'ledger')) renderShell();
    return { fetchedCount: list.length, changedCount, addedCount, ledgerChangedCount, ledgerAddedCount };
  }

  function normalizeAssignedDesignTaskRow(item) {
    if (!item || typeof item !== 'object') return null;
    const sku = String(item.product_code || item.productCode || item.code || '').trim().toUpperCase();
    if (!sku) return null;
    const projectId = String(item.id || item.project_id || item.chemical_id || item.project_row_id || item.projectRowId || '').trim();
    const benchmarkImageUrl = getApiAssetUrl(item.main_pic || item.mainPic || '', 0);
    const productListImageUrl = getApiAssetUrl(item.pic || item.product_pic || item.product_image || '', 0);
    const developerName = cleanName(item.dev_work_user_name || item.dev_head_user_name || '');
    const developerText = [developerName, item.dev_work_user_jobtitlename || item.dev_head_user_jobtitlename || ''].filter(Boolean).join(' ');
    const planStock = item.is_plan_stock === true || item.is_plan_stock === 1
      ? '\u662f'
      : (item.is_plan_stock === false || item.is_plan_stock === 0 ? '\u5426' : cleanProjectListCell(item.is_plan_stock));
    return {
      sku,
      rowId: projectId,
      projectId,
      productId: String(item.product_id || '').trim(),
      productVersionId: String(item.product_main_id || item.product_version_id || '').trim(),
      developerText,
      developerName,
      brand: cleanName(item.brand_name || item.product_brand_name || ''),
      name: normalizeProductNameValue(cleanName(item.product_name || item.dev_product_name || '')),
      benchmarkImageUrl,
      referenceUrl: String(item.main_url || item.reference_url || item.referenceUrl || '').trim(),
      developmentAdvice: cleanProjectListCell(item.remark || item.dev_proposals),
      artPriority: cleanProjectListCell(item.priority_label),
      projectStatus: cleanProjectListCell(item.status_format || item.status),
      designType: cleanProjectListCell(item.design_type_label),
      specificationText: cleanProjectListCell(item.specification),
      productListImageUrl,
      designAssignedAt: String(item.design_assign_at || item.designAssignedAt || '').trim(),
      developmentAssignedAt: String(item.dev_assign_at || item.developmentAssignedAt || '').trim(),
      projectCreatedAt: String(item.create_at || item.audit_at || item.projectCreatedAt || '').trim(),
      departmentName: cleanProjectListCell(item.design_work_user_department_name || item.dev_work_user_department_name),
      projectOwnerName: cleanProjectListCell(item.design_work_user_name || item.dev_work_user_name),
      promotionStatus: cleanProjectListCell(item.promote_status_format),
      listingStatus: cleanProjectListCell(item.sale_status_format),
      bomStatus: cleanProjectListCell(item.bom_status_format),
      requiresPlanStock: planStock,
      bomAuditStatus: cleanProjectListCell(item.audit_bom_status_format),
      plmCategory: cleanProjectListCell(item.category_name),
      productType: cleanProjectListCell(item.product_type_format || item.product_type),
      productTypeValue: item.product_type,
    };
  }

  function getApiListTotal(payload) {
    const data = getApiPayloadDataObject(payload);
    return Number(data.total || payload && payload.total || 0) || 0;
  }

  async function fetchAssignedDesignTaskRows() {
    const rows = [];
    let total = 0;
    for (let page = 1; page <= 100; page += 1) {
      const payload = await fetchPlmJson(ASSIGNED_DESIGN_TASK_ENDPOINT + '?page=' + page + '&pageSize=' + ASSIGNED_DESIGN_TASK_PAGE_SIZE
        + '&sort_field=' + encodeURIComponent(ASSIGNED_DESIGN_TASK_SORT_FIELD)
        + '&sort_asc=' + String(ASSIGNED_DESIGN_TASK_SORT_ASC));
      if (payload && payload.success === false) {
        throw new Error(formatPlmApiMessage(payload.msg) || formatPlmApiMessage(payload.message) || '\u8bbe\u8ba1\u4efb\u52a1 API \u8fd4\u56de\u5931\u8d25');
      }
      const pageRows = getApiListItems(payload);
      total = getApiListTotal(payload) || total;
      rows.push(...pageRows);
      if (!pageRows.length || (total && rows.length >= total) || pageRows.length < ASSIGNED_DESIGN_TASK_PAGE_SIZE) break;
    }
    const deduped = new Map();
    rows.forEach((item) => {
      const row = normalizeAssignedDesignTaskRow(item);
      if (!row || !row.designAssignedAt) return;
      const previous = deduped.get(row.sku);
      if (!previous || parseSkuListTime(row.designAssignedAt) >= parseSkuListTime(previous.designAssignedAt)) deduped.set(row.sku, row);
    });
    return Array.from(deduped.values());
  }

  function syncAssignedDesignTasksFromApi(options) {
    if (!state.settings.collectionEnabled) return Promise.resolve({ fetchedCount: 0, changedCount: 0, addedCount: 0, ledgerChangedCount: 0, ledgerAddedCount: 0, disabled: true });
    if (state.assignedDesignTaskSyncPromise) return state.assignedDesignTaskSyncPromise;
    const now = Date.now();
    const lastStartedAt = Number(state.assignedDesignTaskSyncLastStartedAt || 0);
    const elapsed = now - lastStartedAt;
    if (lastStartedAt > 0 && elapsed >= 0 && elapsed < ASSIGNED_DESIGN_TASK_SYNC_COOLDOWN_MS) {
      return Promise.resolve({
        fetchedCount: 0,
        changedCount: 0,
        addedCount: 0,
        ledgerChangedCount: 0,
        ledgerAddedCount: 0,
        skipped: true,
        cooldownRemainingMs: ASSIGNED_DESIGN_TASK_SYNC_COOLDOWN_MS - elapsed,
      });
    }
    state.assignedDesignTaskSyncLastStartedAt = now;
    const request = (async () => {
      const rows = await fetchAssignedDesignTaskRows();
      return syncProjectListRowsToCache(rows, {
        source: 'assigned-design-api',
        ledgerNote: '\u6211\u7684\u8be6\u60c5 API \u81ea\u52a8\u52a0\u5165',
        ledgerLog: '\u6211\u7684\u8be6\u60c5\u5df2\u901a\u8fc7\u8bbe\u8ba1\u4efb\u52a1 API \u540c\u6b65\u5230\u4eca\u65e5\u5de5\u4f5c\u53f0',
        cacheLog: '\u6211\u7684\u8be6\u60c5\u5df2\u901a\u8fc7\u8bbe\u8ba1\u4efb\u52a1 API \u66f4\u65b0\u672c\u5730\u7f13\u5b58',
        render: options && options.deferRender ? false : undefined,
      });
    })();
    const task = request.finally(() => {
      if (state.assignedDesignTaskSyncPromise === task) state.assignedDesignTaskSyncPromise = null;
    });
    state.assignedDesignTaskSyncPromise = task;
    return task;
  }

  function collectProjectAllListRows() {
    const headerCells = Array.from(document.querySelectorAll('table.vxe-table--header'))
      .map((table) => Array.from(table.querySelectorAll('thead th')))
      .find((cells) => {
        const names = cells.map((cell) => normalizeProjectListHeader(cell.innerText || cell.textContent));
        return names.includes('\u5546\u54c1\u7f16\u7801')
          && (names.includes('\u9879\u76ee\u72b6\u6001') || names.includes('\u8bbe\u8ba1\u7c7b\u578b') || names.includes('BOM\u72b6\u6001') || names.includes('\u5bf9\u6807\u4ea7\u54c1\u94fe\u63a5'));
      }) || [];
    if (!headerCells.length) return [];
    const headers = headerCells.map((cell) => normalizeProjectListHeader(cell.innerText || cell.textContent));
    const indexOf = (name) => headers.indexOf(name);
    const skuIndex = indexOf('\u5546\u54c1\u7f16\u7801');
    const imageIndex = indexOf('\u5546\u54c1\u56fe\u7247');
    const body = Array.from(document.querySelectorAll('table.vxe-table--body'))
      .find((table) => Array.from(table.querySelectorAll('tbody tr')).some((row) => row.children.length > imageIndex && /SKU\d+/i.test(row.innerText || row.textContent || '')));
    if (!body || skuIndex < 0) return [];
    const textAt = (cells, name) => {
      const index = indexOf(name);
      return index >= 0 && cells[index] ? cleanProjectListCell(cells[index].innerText || cells[index].textContent) : '';
    };
    const imageAt = (cells, name) => {
      const index = indexOf(name);
      const cell = index >= 0 ? cells[index] : null;
      if (!cell) return '';
      const image = cell.querySelector('img');
      const candidates = image ? [
        image.getAttribute('data-src'),
        image.getAttribute('data-original'),
        image.getAttribute('data-url'),
        image.currentSrc,
        image.src,
        image.getAttribute('src'),
      ] : [];
      const link = cell.querySelector('a[href]');
      if (link) candidates.push(link.href || link.getAttribute('href'));
      return candidates.map((value) => String(value || '').trim()).find((value) => value && !/^data:image\//i.test(value)) || '';
    };
    return Array.from(body.querySelectorAll('tbody tr')).map((row) => {
      const cells = Array.from(row.children);
      const skuText = cells[skuIndex] ? compactText(cells[skuIndex].innerText || cells[skuIndex].textContent) : '';
      const sku = ((skuText.match(/SKU\d+/i) || [])[0] || '').toUpperCase();
      const developerText = textAt(cells, '\u5f00\u53d1\u4eba\u5458');
      return {
        sku,
        rowId: row.getAttribute('rowid') || '',
        developerText,
        developerName: (developerText.match(/^[\u4e00-\u9fa5A-Za-z ._-]+?(?=\s+(?:\u5f00\u53d1|\u4e3b\u7ba1|\u7ecf\u7406|\u4e13\u5458)|\s*\||$)/) || [])[0] || '',
        brand: textAt(cells, '\u54c1\u724c'),
        name: textAt(cells, '\u5546\u54c1\u540d\u79f0'),
        benchmarkImageUrl: imageAt(cells, '\u5bf9\u6807\u56fe\u7247'),
        referenceUrl: textAt(cells, '\u5bf9\u6807\u4ea7\u54c1\u94fe\u63a5'),
        developmentAdvice: textAt(cells, '\u5f00\u53d1\u5efa\u8bae'),
        artPriority: textAt(cells, '\u7f8e\u5de5\u5904\u7406\u4f18\u5148\u7ea7'),
        projectStatus: textAt(cells, '\u9879\u76ee\u72b6\u6001'),
        designType: textAt(cells, '\u8bbe\u8ba1\u7c7b\u578b'),
        specificationText: textAt(cells, '\u89c4\u683c\u578b\u53f7'),
        productListImageUrl: imageAt(cells, '\u5546\u54c1\u56fe\u7247'),
        designAssignedAt: textAt(cells, '\u8bbe\u8ba1\u5206\u914d\u65f6\u95f4'),
        projectCreatedAt: textAt(cells, '\u521b\u5efa\u65f6\u95f4'),
        departmentName: textAt(cells, '\u6240\u5728\u90e8\u95e8'),
        projectOwnerName: textAt(cells, '\u7528\u6237\u540d\u79f0'),
        promotionStatus: textAt(cells, '\u63a8\u5e7f\u72b6\u6001'),
        listingStatus: textAt(cells, '\u4e0a\u67b6\u72b6\u6001'),
        bomStatus: textAt(cells, 'BOM\u72b6\u6001'),
        requiresPlanStock: textAt(cells, '\u662f\u5426\u8981\u6c42\u8ba1\u5212\u5907\u8d27'),
        bomAuditStatus: textAt(cells, '\u5ba1\u6838Bom\u72b6\u6001'),
        plmCategory: textAt(cells, '\u54c1\u7c7b'),
      };
    }).filter((row) => row.sku && row.rowId);
  }

  function normalizeProjectListHeader(value) {
    return compactText(value).replace(/^\*\s*/, '').replace(/[\ue000-\uf8ff]/g, '').trim();
  }

  function cleanProjectListCell(value) {
    const text = compactText(value);
    return text === '--' ? '' : text;
  }

  function isWestmonthLoginPage() {
    return /auth\.westmonth\.com\/auth\/login/.test(location.href);
  }

  function autoClickWestmonthLogin() {
    const tryClick = () => {
      const inputs = Array.from(document.querySelectorAll('input')).filter(isVisibleElement);
      const account = inputs.find((input) => /工号|手机号|邮箱|账号|用户名/i.test(input.placeholder || '') || input.type === 'text');
      const password = inputs.find((input) => input.type === 'password' || /密码/i.test(input.placeholder || ''));
      if (!account || !password || !account.value || !password.value) return false;
      const button = findWestmonthLoginButton();
      if (!button || !isActionButtonReady(button)) return false;
      button.click();
      return true;
    };
    if (tryClick()) return;
    const startedAt = Date.now();
    const timer = window.setInterval(() => {
      if (tryClick() || Date.now() - startedAt > 15000) window.clearInterval(timer);
    }, 500);
  }

  function findWestmonthLoginButton() {
    return Array.from(document.querySelectorAll('button, [role="button"], input[type="button"], input[type="submit"]'))
      .filter(isVisibleElement)
      .find((el) => {
        const text = compactText(el.innerText || el.textContent || el.value).replace(/\s+/g, '');
        return text === '\u767b\u5f55' || /^log\s*in$/i.test(text);
      }) || null;
  }

  function startUploadQueueSync() {
    let refreshTimer = 0;
    const refresh = () => {
      state.uploadQueue = loadUploadQueue();
      state.uploadHistory = loadUploadHistory();
      const mode = isUploadWorkerPage() ? getUploadWorkerModeFromUrl() : normalizeUploadMode(state.uploadMode);
      state.uploadWorkerMode = mode;
      state.uploadRunning = loadUploadWorkerRunning(mode);
      if (state.view === 'upload') {
        if (!refreshUploadViewInPlace(ensurePanel())) renderShell();
      }
      else if (state.uploadExpanded) renderShell();
    };
    const scheduleRefresh = (resetHistoryPage) => {
      if (resetHistoryPage && state.uploadView === 'history') state.uploadHistoryPage = 1;
      window.clearTimeout(refreshTimer);
      refreshTimer = window.setTimeout(refresh, 0);
    };
    if (typeof GM_addValueChangeListener === 'function') {
      GM_addValueChangeListener(UPLOAD_QUEUE_KEY, (_name, _oldValue, _newValue, remote) => {
        if (!remote && isUploadWorkerPage()) return;
        scheduleRefresh(false);
      });
      GM_addValueChangeListener(UPLOAD_HISTORY_KEY, () => {
        scheduleRefresh(true);
        scheduleDesktopBridgeSnapshot();
      });
      GM_addValueChangeListener(UPLOAD_WORKER_KEY, () => scheduleRefresh(false));
      GM_addValueChangeListener(UPLOAD_WORKER_STATES_KEY, () => scheduleRefresh(false));
    }
    window.addEventListener('storage', (event) => {
      if (event.key === UPLOAD_QUEUE_KEY || event.key === UPLOAD_HISTORY_KEY || event.key === UPLOAD_WORKER_KEY || event.key === UPLOAD_WORKER_STATES_KEY) refresh();
      if (event.key === UPLOAD_HISTORY_KEY) scheduleDesktopBridgeSnapshot();
    });
    window.setInterval(refresh, 5000);
  }

  function handleDrawerState() {
    if (state.view === 'batchExcel' || state.view === 'tools') return;
    const lockedSku = state.openingProjectDetailSku || '';
    const drawer = getProjectDrawer();
    if (!drawer) {
      if (lockedSku) return;
      scheduleDrawerClosedCollapse();
      return;
    }

    const text = getVisibleText(drawer);
    const sku = getProjectDrawerHeaderSku(drawer);
    if (!sku) return;
    if (state.drawerTabFlowSku && ((state.drawerTabFlowDrawer && drawer !== state.drawerTabFlowDrawer) || (sku && sku !== state.drawerTabFlowSku))) {
      stopScan();
      cancelDrawerTabFlow();
    }
    if (sku && state.selectedSku && sku !== state.selectedSku) {
      state.copywritingMode = false;
      state.copywritingError = '';
      state.copywritingStatus = '';
    }
    if (lockedSku && sku && sku !== lockedSku) return;
    if (lockedSku && !sku && state.openingProjectDetail) return;
    if (state.userCollapsedPanel && state.manuallyCollapsedForSku && state.manuallyCollapsedForSku === (sku || state.sku)) return;
    const shouldAdoptProgrammaticDetail = sku && state.openingProjectDetailSku && sku === state.openingProjectDetailSku;
    if (!shouldAdoptProgrammaticDetail && (state.view === 'sizeImage' || state.view === 'parameterImage')) {
      state.drawer = drawer;
      state.sku = sku || state.sku || '';
      return;
    }
    if (!shouldAdoptProgrammaticDetail && (state.view === 'about' || state.view === 'upload')) {
      state.drawer = drawer;
      state.sku = sku || state.sku || '';
      if (sku) state.selectedSku = sku;
      return;
    }
    const changed = drawer !== state.drawer || (sku && sku !== state.sku);
    if (state.scanRunning && drawer === state.drawer) {
      if (sku && sku !== state.sku) {
        state.sku = sku;
        state.scanTargetSku = sku;
        state.scanData = normalizeData(loadData(sku) || {
          sku,
          name: cleanName((text.match(/\u5546\u54c1\u540d\u79f0[:\uff1a]\s*([^\n]+)/) || [])[1] || ''),
        });
      }
      return;
    }
    if (!changed && state.manuallyCollapsedForSku && state.manuallyCollapsedForSku === (sku || state.sku)) return;
    if (!changed) return;
    state.manuallyCollapsedForSku = '';
    if (shouldAdoptProgrammaticDetail) {
      state.openingProjectDetail = false;
      state.openingProjectDetailSku = '';
    }

    const cached = sku ? loadData(sku) : null;
    if (cached) {
      state.drawer = drawer;
      state.sku = sku || '';
      state.data = normalizeData(cached);
      const projectStatus = extractProjectStatus(text);
      if (projectStatus && projectStatus !== state.data.projectStatus) {
        state.data = normalizeData({ ...state.data, projectStatus });
        saveData(sku, state.data);
      }
      state.selectedSku = sku;
      state.view = 'detail';
      resetExcelState();
      expandPanel();
      upsertIndex(state.data);
      stopScan();
      if (!shouldSkipLedgerDrawer(drawer)) {
        upsertDailyLedgerFromData(state.data, { status: '待定稿', stage: '待定稿', note: '打开详情自动记录', requireCurrentMonth: true });
      }
      renderShell(L.scanning);
      scheduleDrawerProductFlow(state.data, { reason: 'cached-open', includeScanTabs: true });
      return;
    }

    state.drawer = drawer;
    state.sku = sku || '';
    state.data = sku ? normalizeData({ sku, name: cleanName((text.match(/\u5546\u54c1\u540d\u79f0[:\uff1a]\s*([^\n]+)/) || [])[1] || ''), projectStatus: extractProjectStatus(text) }) : null;
    state.selectedSku = sku || '';
    state.view = 'detail';
    resetExcelState();
    expandPanel();
    if (state.settings.collectionEnabled) {
      resetRound();
      state.scanTargetSku = sku || '';
      startScan();
      return;
    }
    renderShell();
  }

  function scheduleDrawerClosedCollapse() {
    const hadDrawer = Boolean(state.drawer || state.sku);
    stopScan();
    cancelDrawerTabFlow();
    stopMaterialWatch();
    stopManualTabRead();
    state.drawer = null;
    state.sku = '';
    state.observedDrawer = null;
    state.observedSku = '';
    state.observedTab = '';
    if (hadDrawer) collapsePanel(true);
  }

  function resetRound() {
    stopScan();
    cancelDrawerTabFlow();
    state.scanRunning = false;
    state.scanTargetSku = '';
    state.scanData = null;
  }

  function startScan(options) {
    const opts = options || {};
    if (!state.settings.collectionEnabled) return;
    const drawer = getProjectDrawer();
    if (!drawer) {
      showToast('\u8bf7\u5148\u6253\u5f00\u9879\u76ee\u8be6\u60c5');
      return;
    }
    stopScan();
    const drawerSku = getProjectDrawerHeaderSku(drawer);
    const requestedSku = state.scanTargetSku || state.sku || '';
    if (!drawerSku || (requestedSku && requestedSku !== drawerSku)) {
      state.scanRunning = true;
      state.scanTimer = window.setTimeout(startScan, 250);
      return;
    }
    const targetSku = drawerSku;
    if (targetSku) {
      state.scanTargetSku = targetSku;
      if (!state.scanData || state.scanData.sku !== targetSku) {
        const activeData = state.data && state.data.sku === targetSku ? state.data : null;
        state.scanData = normalizeData(activeData || loadData(targetSku) || { sku: targetSku });
      }
    }
    lockLoadingTip(targetSku || state.selectedSku || '');
    state.scanRunning = true;
    if (!isLoadingTipVisible()) renderShell(L.scanning);
    scheduleDrawerProductFlow(state.scanData || { sku: targetSku }, {
      reason: 'scan',
      includeScanTabs: true,
      replace: true,
      forceAllTabs: Boolean(opts.forceAllTabs),
    });
  }

  async function refreshSelectedData() {
    if (!state.settings.collectionEnabled) {
      showToast('数据采集已关闭');
      return;
    }
    const targetSku = (state.data && state.data.sku) || state.selectedSku || '';
    if (!targetSku) {
      showToast(L.excelNeedData);
      return;
    }

    state.view = 'detail';
    stopMaterialWatch();
    stopScan();
    expandPanel();

    let drawer = getProjectDrawer();
    const drawerText = drawer ? getVisibleText(drawer) : '';
    if (!drawer || !drawerText.includes(targetSku)) {
      renderShell('\u6b63\u5728\u6253\u5f00\u6b63\u786e\u7f16\u7801\u8be6\u60c5...');
      await openSelectedProjectDetail();
      drawer = await waitFor(() => getProjectDrawerForSku(targetSku), 5000, 150);
      if (!drawer) {
        showToast(L.openDetailFailed);
        renderShell();
        return;
      }
    }

    state.drawer = drawer;
    state.sku = targetSku;
    state.selectedSku = targetSku;
    state.data = createRefreshSeedData(targetSku);
    resetExcelState();
    resetRound();
    state.scanTargetSku = targetSku;
    renderShell(L.scanning);
    startScan({ forceAllTabs: true });
  }

  function createRefreshSeedData(sku) {
    const cached = normalizeData(loadData(sku) || {});
    const preservedImageSource = /^(?:effectImage|productListImage)$/.test(cached.skuImageSource || '') ? cached.skuImageSource : '';
    return normalizeData({
      sku,
      name: cached.name || '',
      brand: cached.brand || '',
      manualCategory: cached.manualCategory || '',
      aiProductType: cached.aiProductType || '',
      aiCategory: cached.aiCategory || '',
      productType: cached.productType || '',
      category: cached.category || '',
      plmCategory: cached.plmCategory || '',
      departmentName: cached.departmentName || '',
      manualFieldOverrides: cached.manualFieldOverrides || {},
      recentFieldChanges: Array.isArray(cached.recentFieldChanges) ? cached.recentFieldChanges : [],
      projectRowId: cached.projectRowId || '',
      projectId: cached.projectId || '',
      copywriting: cached.copywriting || null,
      copywritingIngredientEnglish: cached.copywritingIngredientEnglish || '',
      copywritingIngredientChinese: cached.copywritingIngredientChinese || '',
      copywritingIngredientSplit: Boolean(cached.copywritingIngredientSplit),
      ingredientEnglish: cached.ingredientEnglish || '',
      ingredientChinese: cached.ingredientChinese || '',
      ingredientItems: Array.isArray(cached.ingredientItems) ? cached.ingredientItems : [],
      ingredientPdfFileName: cached.ingredientPdfFileName || '',
      ingredientPdfHash: cached.ingredientPdfHash || '',
      ingredientPdfModel: cached.ingredientPdfModel || '',
      ingredientPdfUpdatedAt: cached.ingredientPdfUpdatedAt || '',
      ingredientNormalizerVersion: cached.ingredientNormalizerVersion || '',
      ingredientSource: cached.ingredientSource || '',
      ingredientWordFileName: cached.ingredientWordFileName || '',
      ingredientWordHash: cached.ingredientWordHash || '',
      ingredientWordUpdatedAt: cached.ingredientWordUpdatedAt || '',
      tailSealLengthValue: cached.tailSealLengthValue || '',
      purchasePrice: cached.purchasePrice || '',
      purchasePriceSource: cached.purchasePriceSource || '',
      purchasePriceUpdatedAt: cached.purchasePriceUpdatedAt || '',
      seenDesign: cached.seenDesign,
      productListImageUrl: cached.productListImageUrl || '',
      productListImageFallbackUrl: cached.productListImageFallbackUrl || '',
      benchmarkImageUrl: cached.benchmarkImageUrl || '',
      benchmarkImageFallbackUrl: cached.benchmarkImageFallbackUrl || '',
      skuImageUrl: preservedImageSource ? (cached.skuImageUrl || '') : '',
      skuImageFallbackUrl: preservedImageSource ? (cached.skuImageFallbackUrl || '') : '',
      skuImageSource: preservedImageSource,
    });
  }

  function stopScan() {
    clearScanLoadingTipTimer();
    if (state.scanTimer) {
      window.clearTimeout(state.scanTimer);
      state.scanTimer = 0;
    }
    state.scanRunning = false;
  }

  function clearScanLoadingTipTimer() {
    if (!state.scanLoadingTipTimer) return;
    window.clearTimeout(state.scanLoadingTipTimer);
    state.scanLoadingTipTimer = 0;
  }

  function armScanLoadingTipTimeout(sku, token) {
    clearScanLoadingTipTimer();
    state.scanLoadingTipTimer = window.setTimeout(() => {
      state.scanLoadingTipTimer = 0;
      if (
        !state.scanRunning
        || state.drawerTabFlowToken !== token
        || state.drawerTabFlowSku !== sku
      ) return;
      state.scanRunning = false;
      if (state.apiReadStatus && state.apiReadStatus.sku === sku && state.apiReadStatus.phase === 'loading') {
        setApiReadStatus(sku, 'loading', '正在后台读取 PLM 数据');
      }
      if (state.selectedSku === sku && state.view === 'detail') renderShell();
      addLog('info', '详情前台提示超时，已切换为后台读取', sku + ' | ' + SCAN_FOREGROUND_LOADING_TIMEOUT_MS + 'ms');
    }, SCAN_FOREGROUND_LOADING_TIMEOUT_MS);
  }

  function stopManualTabRead() {
    if (state.manualCollectTimer) {
      window.clearTimeout(state.manualCollectTimer);
      state.manualCollectTimer = 0;
    }
  }

  function observeManualTabRead() {
    const drawer = getProjectDrawer();
    if (!drawer || state.scanRunning || !state.settings.collectionEnabled) return;
    const sku = getProjectDrawerHeaderSku(drawer);
    const tab = getActiveTabText(drawer);
    if (!sku || !tab) return;
    if (drawer !== state.observedDrawer || sku !== state.observedSku) {
      state.observedDrawer = drawer;
      state.observedSku = sku;
      state.observedTab = tab;
      return;
    }
    if (tab === state.observedTab) return;
    state.observedTab = tab;
    stopManualTabRead();
    state.manualCollectTimer = window.setTimeout(() => readCurrentManualTab(drawer, sku, tab), 420);
  }

  function readCurrentManualTab(drawer, sku, tab) {
    state.manualCollectTimer = 0;
    if (!state.settings.collectionEnabled || state.scanRunning || drawer !== getProjectDrawerForSku(sku) || getActiveTabText(drawer) !== tab) return;
    const next = extractData(drawer, { forceSkuImage: tab === L.productTab });
    if (!next.sku || next.sku !== sku) return;
    const merged = mergeData(loadData(sku) || (state.data && state.data.sku === sku ? state.data : { sku }), next);
    const previous = normalizeData(loadData(sku) || (state.data && state.data.sku === sku ? state.data : { sku }));
    const changed = hasMeaningfulDataChange(previous, merged);
    if (changed) {
      saveData(sku, merged);
      if (state.selectedSku === sku) renderShell();
    }
    if (tab === L.productTab) {
      scheduleDrawerProductFlow(merged, { reason: 'manual-product-tab', includeScanTabs: false, replace: true });
    }
  }

  function stopMaterialWatch() {
    if (state.materialWatchTimer) {
      window.clearTimeout(state.materialWatchTimer);
      state.materialWatchTimer = 0;
    }
  }

  function checkMaterialOnce() {
    const targetSku = state.scanTargetSku || state.sku || (state.data && state.data.sku) || '';
    const drawer = targetSku ? getProjectDrawerForSku(targetSku) : null;
    const trackedData = state.scanData && state.scanData.sku === targetSku
      ? state.scanData
      : normalizeData(loadData(targetSku) || {});
    if (!drawer || !targetSku || !trackedData.sku) {
      stopMaterialWatch();
      return;
    }

    state.materialWatchAttempts += 1;
    const text = getVisibleText(drawer);
    const activeTabText = getActiveTabText(drawer);
    const onMaterial = activeTabText === L.materialTab || /\u7269\u6599\u7f16\u7801.*\u7269\u6599\u540d\u79f0.*\u89c4\u683c\u578b\u53f7/.test(text);

    if (!onMaterial) {
      const tab = findTabButton(drawer, L.materialTab);
      if (tab && !isActiveTab(tab)) {
        state.ignoreOutsideClickUntil = Date.now() + 1200;
        tab.click();
      }
    } else {
      const packaging = extractPackaging(drawer);
      if (hasPackagingChanged(trackedData, packaging)) {
        const packageNums = packaging.packageNums || trackedData.packageNums || null;
        const hasInnerCard = hasInnerCardMark(packaging) || hasInnerCardMark(trackedData);
        const productNums = productNumsFromPackage(packageNums, hasInnerCard);
        const updatedData = normalizeData({
          ...trackedData,
          packageSizeText: packaging.packageSizeText || trackedData.packageSizeText,
          packageSizeLabel: packaging.packageSizeLabel || trackedData.packageSizeLabel,
          packageCode: packaging.packageCode || trackedData.packageCode,
          printSizeText: packaging.printSizeText || trackedData.printSizeText,
          printSizeLabel: packaging.printSizeLabel || trackedData.printSizeLabel,
          printCode: packaging.printCode || trackedData.printCode,
          materialDimensionUnitIssues: packaging.materialDimensionUnitIssues,
          packageNums,
          productNums,
          packageSource: packaging.packageSizeText ? L.sourceMaterial : trackedData.packageSource,
          hasInnerCard,
          netContent: packaging.netContent || trackedData.netContent,
          updatedAt: new Date().toLocaleString(),
          updatedAtMs: Date.now(),
        });
        if (state.scanData && state.scanData.sku === targetSku) state.scanData = updatedData;
        saveData(targetSku, updatedData);
        renderShell('\u7269\u6599\u6e05\u5355\u5c3a\u5bf8\u5df2\u66f4\u65b0');
        stopMaterialWatch();
        return;
      }
    }

    if (state.materialWatchAttempts >= MATERIAL_WATCH_ATTEMPTS) {
      stopMaterialWatch();
      renderShell(L.cached);
      return;
    }
    state.materialWatchTimer = window.setTimeout(checkMaterialOnce, SCAN_INTERVAL_MS);
  }

  function hasPackagingChanged(data, packaging) {
    if (!packaging) return false;
    if (packaging.packageSizeText && packaging.packageSizeText !== data.packageSizeText) return true;
    if (packaging.packageSizeLabel && packaging.packageSizeLabel !== data.packageSizeLabel) return true;
    if (hasInnerCardMark(packaging) !== hasInnerCardMark(data)) return true;
    if (packaging.printSizeText && packaging.printSizeText !== data.printSizeText) return true;
    if (packaging.printSizeLabel && packaging.printSizeLabel !== data.printSizeLabel) return true;
    return false;
  }

  function scheduleDrawerProductFlow(data, options) {
    const opts = options || {};
    const sku = String(data && data.sku || '');
    if (!state.settings.collectionEnabled || !sku) return;
    if (!opts.replace && state.drawerTabFlowRunning && state.drawerTabFlowSku === sku) return;
    cancelDrawerTabFlow();
    const token = state.drawerTabFlowToken + 1;
    state.drawerTabFlowToken = token;
    state.drawerTabFlowSku = sku;
    state.drawerTabFlowUserInterrupted = false;
    if (opts.includeScanTabs) {
      state.scanRunning = true;
      state.scanTargetSku = sku;
      state.scanData = normalizeData(data);
      armScanLoadingTipTimeout(sku, token);
    }
    state.drawerTabFlowTimer = window.setTimeout(() => {
      state.drawerTabFlowTimer = 0;
      runDrawerProductFlow(sku, token, opts).catch((error) => {
        addLog('warn', '\u4ea7\u54c1\u4fe1\u606f\u96c6\u4e2d\u83b7\u53d6\u5931\u8d25', sku + ' | ' + formatErrorMessage(error));
      });
    }, opts.reason === 'cached-open' ? 220 : 0);
  }

  function hasCurrentCopywritingCache(data) {
    const record = normalizeCopywritingRecord(data && data.copywriting);
    return Boolean(record && record.fullText && record.parserVersion === COPYWRITING_PARSER_VERSION);
  }

  function getDrawerCollectionTabs(data, includeScanTabs, forceAllTabs) {
    if (!includeScanTabs) return [L.productTab];
    if (forceAllTabs) return ['\u9879\u76ee\u4fe1\u606f', L.materialTab, L.productTab];
    const cached = normalizeData(data || {});
    const tabs = [];
    const hasProjectCache = Boolean(cached.name && cached.projectStatus);
    if (!hasProjectCache || (!cached.referenceUrl && !cached.benchmarkLink)) tabs.push('\u9879\u76ee\u4fe1\u606f');
    const hasPackageDimensions = Boolean(cached.packageLength && cached.packageWidth && cached.packageHeight);
    const hasMaterialUnitIssue = Boolean(getMaterialDimensionUnitIssue(cached, 'package') || getMaterialDimensionUnitIssue(cached, 'print'));
    const missingMaterialSize = !hasPackageDimensions && !cached.printSizeText && !hasMaterialUnitIssue;
    const missingPackageSize = Boolean((cached.packageCode || cached.packageSizeLabel) && !cached.packageSizeText);
    const missingPrintSize = Boolean((cached.printCode || cached.printSizeLabel) && !cached.printSizeText);
    const missingPackageLabel = Boolean((cached.packageCode || cached.packageSizeText) && !cached.packageSizeLabel);
    const missingPrintLabel = Boolean((cached.printCode || cached.printSizeText) && !cached.printSizeLabel);
    const hasIngredientCache = Boolean(cached.ingredientChinese || cached.ingredientEnglish || cached.plmIngredientText);
    const ingredientCheckFresh = Number(cached.plmIngredientParserVersion || 0) === PLM_INGREDIENT_CACHE_VERSION
      && Number(cached.plmIngredientCheckedAt || 0) > 0
      && Date.now() - Number(cached.plmIngredientCheckedAt || 0) < PLM_INGREDIENT_CHECK_WINDOW_MS;
    if (!cached.seenMaterial || missingMaterialSize || missingPackageSize || missingPrintSize || missingPackageLabel || missingPrintLabel) tabs.push(L.materialTab);
    if (!cached.seenProduct || !cached.grossWeight || !hasCurrentCopywritingCache(cached) || (!hasIngredientCache && !ingredientCheckFresh)) tabs.push(L.productTab);
    return tabs;
  }

  function isDrawerProductFlowCurrent(sku, token, drawer) {
    return Boolean(
      !state.drawerTabFlowUserInterrupted &&
      state.drawerTabFlowToken === token &&
      state.drawerTabFlowSku === sku &&
      drawer && drawer === getProjectDrawerForSku(sku) &&
      getProjectDrawerHeaderSku(drawer) === sku
    );
  }

  async function waitForStableProjectDrawerIdentity(drawer, sku, timeout) {
    const startedAt = Date.now();
    let stableSince = 0;
    while (Date.now() - startedAt < (Number(timeout) || 5000)) {
      if (getProjectDrawerHeaderSku(drawer) === sku && drawer === getProjectDrawerForSku(sku)) {
        if (!stableSince) stableSince = Date.now();
        if (Date.now() - stableSince >= 300) return true;
      } else {
        stableSince = 0;
      }
      await wait(100);
    }
    return false;
  }

  async function runDrawerProductFlow(sku, token, options) {
    const includeScanTabs = Boolean(options && options.includeScanTabs);
    const drawer = getProjectDrawerForSku(sku);
    const identityReady = drawer && await waitForStableProjectDrawerIdentity(drawer, sku, 5000);
    if (!identityReady || state.drawerTabFlowToken !== token || state.drawerTabFlowSku !== sku) {
      if (state.drawerTabFlowToken === token) {
        if (includeScanTabs) {
          stopScan();
          state.scanTargetSku = '';
          state.scanData = null;
          renderShell(L.openDetailFailed);
        }
        state.drawerTabFlowRunning = false;
        state.drawerTabFlowSku = '';
        state.drawerTabFlowDrawer = null;
      }
      return;
    }
    state.drawerTabFlowRunning = true;
    state.drawerTabFlowDrawer = drawer;
    const scanSeed = includeScanTabs && state.scanData && state.scanData.sku === sku ? state.scanData : null;
    let merged = normalizeData(scanSeed || loadData(sku) || (state.data && state.data.sku === sku ? state.data : { sku }));
    const apiBaseline = normalizeData(merged);
    let apiDataSaved = false;
    try {
      const apiPackaging = await fetchApiMaterialPackaging(merged);
      if (apiPackaging && (apiPackaging.packageSizeText || apiPackaging.printSizeText || apiPackaging.hasInnerCard || apiPackaging.netContent || apiPackaging.grossWeight)) {
        merged = normalizeData({
          ...mergeApiPackagingData(merged, apiPackaging),
          packageSource: resolveApiMaterialPackageSource(merged, apiPackaging),
          updatedAt: new Date().toLocaleString(),
          updatedAtMs: Date.now(),
        });
        if (includeScanTabs) state.scanData = merged;
      }
      const tabs = getDrawerCollectionTabs(merged, includeScanTabs, Boolean(options && options.forceAllTabs));
      const refreshProductPage = tabs.includes(L.productTab);
      for (const tab of tabs) {
        const ready = await switchDrawerTab(drawer, tab, { flowToken: token, timeout: 4500 });
        if (!ready || !isDrawerProductFlowCurrent(sku, token, drawer)) return;
        let live = extractData(drawer, { forceSkuImage: tab === L.productTab });
        if (live.sku !== sku) return;
        merged = mergeData(merged, live);
        const needsShortReread = (tab === '\u9879\u76ee\u4fe1\u606f' && !live.name && !live.projectStatus)
          || (tab === L.materialTab && !live.seenMaterial)
          || (tab === L.productTab && (!live.seenProduct || !live.grossWeight));
        if (needsShortReread) {
          if (tab === L.productTab && !live.grossWeight) await waitFor(() => getGrossWeightValue(drawer), 2600, 120);
          else await wait(280);
          if (!isDrawerProductFlowCurrent(sku, token, drawer)) return;
          live = extractData(drawer, { forceSkuImage: tab === L.productTab });
          if (live.sku !== sku) return;
          merged = mergeData(merged, live);
        }
        if (tab === L.productTab && requiresSkuImage(merged) && !getProductThumbUrl(merged)) {
          await waitForProductInfoImage(drawer, 420);
          if (!isDrawerProductFlowCurrent(sku, token, drawer)) return;
          live = extractData(drawer, { forceSkuImage: true });
          if (live.sku !== sku) return;
          merged = mergeData(merged, live);
        }
        if (includeScanTabs) state.scanData = merged;
      }
      const apiPackagingFinal = await fetchApiMaterialPackaging(merged);
      if (apiPackagingFinal && (apiPackagingFinal.packageSizeText || apiPackagingFinal.printSizeText || apiPackagingFinal.hasInnerCard || apiPackagingFinal.netContent || apiPackagingFinal.grossWeight)) {
        merged = normalizeData({
          ...mergeApiPackagingData(merged, apiPackagingFinal),
          packageSource: resolveApiMaterialPackageSource(merged, apiPackagingFinal),
          updatedAt: new Date().toLocaleString(),
          updatedAtMs: Date.now(),
        });
        if (apiPackagingFinal.packageSizeText || apiPackagingFinal.printSizeText || apiPackagingFinal.netContent || apiPackagingFinal.grossWeight) {
          addLog('success', '已用 PLM 接口更新产品与包材数据', sku + ' | 纸盒 ' + (apiPackagingFinal.packageSizeText || '无') + ' | 标签/印刷 ' + (apiPackagingFinal.printSizeText || '无') + ' | 净含量 ' + (apiPackagingFinal.netContent || '无') + ' | 毛重 ' + (apiPackagingFinal.grossWeight || '无'));
        }
      }
      const apiDomesticThirdTierPrice = extractApiDomesticThirdTierPrice([apiPackagingFinal, apiPackagingFinal && apiPackagingFinal.apiProject]);
      if (apiDomesticThirdTierPrice && !normalizeLedgerPurchasePrice(merged.purchasePrice)) {
        merged = normalizeData({
          ...merged,
          purchasePrice: apiDomesticThirdTierPrice,
          purchasePriceSource: 'plm-api-domestic-third-tier',
          purchasePriceUpdatedAt: new Date().toLocaleString(),
        });
        addLog('success', '已用 PLM 接口读取国内三档价格', sku + ' | ' + apiDomesticThirdTierPrice);
      }
      if (!isDrawerProductFlowCurrent(sku, token, drawer)) return;
      saveData(sku, merged, { changeSource: 'PLM 接口' });
      apiDataSaved = true;
      if (state.selectedSku === sku) state.data = normalizeData(loadData(sku) || merged);
      if (includeScanTabs && !shouldSkipLedgerDrawer(drawer)) {
        upsertDailyLedgerFromData(merged, { status: '\u5f85\u5b9a\u7a3f', stage: '\u5f85\u5b9a\u7a3f', note: '\u6253\u5f00\u8be6\u60c5\u81ea\u52a8\u8bb0\u5f55', requireCurrentMonth: true });
      }

      if (merged.projectStatus === '\u5df2\u5b8c\u6210' && !normalizeLedgerPurchasePrice(merged.purchasePrice)) {
        const stockReady = await switchDrawerTab(drawer, '\u5907\u8d27\u4fe1\u606f', { flowToken: token, timeout: 3800 });
        if (stockReady && isDrawerProductFlowCurrent(sku, token, drawer)) {
          const price = await waitFor(() => extractDomesticTierPrice(drawer), 2200, 120);
          if (price && isDrawerProductFlowCurrent(sku, token, drawer)) merged = cacheDomesticTierPrice(sku, merged, price);
        }
      }

      if (refreshProductPage) {
        if (!isDrawerProductFlowCurrent(sku, token, drawer)) return;
        await switchDrawerTab(drawer, L.productTab, { flowToken: token, timeout: 4500 });
        if (!isDrawerProductFlowCurrent(sku, token, drawer)) return;

        const copywritingData = await hydrateCopywritingForSku(sku, {
          silent: true,
          drawer,
        });
        const copywritingRecord = normalizeCopywritingRecord(copywritingData && copywritingData.copywriting);
        if (!copywritingRecord || !copywritingRecord.fullText) addLog('info', '\u4ea7\u54c1\u4fe1\u606f\u672a\u627e\u5230\u4ea7\u54c1\u6587\u6848 Word', sku);
        const ingredientData = await hydrateIngredientPdfForSku(sku, {
          silent: true,
          drawer,
        });
        if (!ingredientData.ingredientEnglish && !ingredientData.ingredientChinese) {
          addLog('info', '\u4ea7\u54c1\u4fe1\u606f\u672a\u627e\u5230\u6210\u5206\u8868 PDF', sku);
        }
      }
    } finally {
      if (includeScanTabs && isDrawerProductFlowCurrent(sku, token, drawer)) {
        await switchDrawerTab(drawer, L.materialTab, { flowToken: token, timeout: 4500 }).catch(() => false);
      }
      if (state.drawerTabFlowToken === token) {
        if (includeScanTabs) {
          stopScan();
          state.scanTargetSku = '';
          state.scanData = null;
          renderShell(L.scanDone);
        } else if (state.selectedSku === sku) {
          renderShell(L.cached);
        }
        if (apiDataSaved && state.selectedSku === sku) showApiDataChangeNotice(sku, apiBaseline, merged);
        state.drawerTabFlowRunning = false;
        state.drawerTabFlowSku = '';
        state.drawerTabFlowDrawer = null;
      }
    }
  }

  function extractDomesticTierPrice(drawer) {
    if (!drawer || getActiveTabText(drawer) !== '\u5907\u8d27\u4fe1\u606f') return '';
    const labeled = getFormValueByLooseLabel('\u56fd\u5185\u4e09\u6863\u4ef7\u683c', drawer);
    const fromLabel = normalizeLedgerPurchasePrice(String(labeled || '').replace(/^[^\d]*/, ''));
    if (fromLabel) return fromLabel;
    const text = getVisibleText(drawer);
    const match = text.match(/\u56fd\u5185\u4e09\u6863\u4ef7\u683c\s*[:\uff1a]?\s*(?:[\uffe5\u00a5]|RMB)?\s*(\d+(?:\.\d+)?)(?![\d.])/i);
    return normalizeLedgerPurchasePrice(match ? match[1] : '');
  }

  function cacheDomesticTierPrice(sku, data, price, source) {
    const normalizedPrice = normalizeLedgerPurchasePrice(price);
    if (!sku || !normalizedPrice) return data;
    const previousPrice = normalizeLedgerPurchasePrice(data && data.purchasePrice);
    const priceSource = String(source || 'plm-stock-domestic-tier');
    const next = normalizeData({
      ...(data || {}),
      purchasePrice: normalizedPrice,
      purchasePriceSource: priceSource,
      purchasePriceUpdatedAt: new Date().toLocaleString(),
    });
    saveData(sku, next);
    if (state.selectedSku === sku) {
      state.data = next;
      state.excelPurchasePrice = normalizedPrice;
    }
    if (state.excelExtra && state.excelExtra.excelData && state.excelExtra.excelData.sku === sku) {
      state.excelExtra.excelData = next;
    }
    upsertDailyLedgerFromData(next, { purchasePrice: normalizedPrice });
    if (previousPrice !== normalizedPrice) recordCommerceInsight(next, null, { price: normalizedPrice, source: priceSource });
    addLog('success', '\u5df2\u7f13\u5b58\u56fd\u5185\u4e09\u6863\u4ef7\u683c', sku + ' | ' + normalizedPrice);
    return next;
  }

  async function diagnoseMissingDataBeforeSave(data) {
    const missing = getMissingFieldsForData(data);
    if (!missing.length || state.diagnosticRunning) return data;
    const issueMeta = getDataQualityIssueMeta(data, missing);
    if (issueMeta.kind === '\u53ef\u80fd PLM \u7a7a\u503c') return data;

    const drawer = getProjectDrawerForSku(data.sku) || getProjectDrawer();
    if (!drawer) {
      addLog('warn', '\u6570\u636e\u7f3a\u5931\u8bca\u65ad\u8df3\u8fc7', data.sku + ' \u672a\u627e\u5230\u5bf9\u5e94\u62bd\u5c49');
      return attachMissingDiagnostic(data, {
        status: '\u672a\u6267\u884c',
        reason: '\u672a\u627e\u5230\u5bf9\u5e94\u62bd\u5c49',
        beforeMissing: missing,
        afterMissing: missing,
        fixed: [],
        tabs: [],
      });
    }

    const tabs = getDiagnosticTabsForMissing(missing);
    if (!tabs.length) {
      return attachMissingDiagnostic(data, {
        status: '\u672a\u6267\u884c',
        reason: '\u672a\u627e\u5230\u9700\u4e8c\u6b21\u8bfb\u53d6\u7684\u9875\u7b7e',
        beforeMissing: missing,
        afterMissing: missing,
        fixed: [],
        tabs: [],
      });
    }
    state.diagnosticRunning = true;
    addLog('info', '\u5f00\u59cb\u4e8c\u6b21\u8bfb\u53d6\u7f3a\u5931\u6570\u636e', data.sku + ' \u7f3a\uff1a' + missing.join('\u3001') + ' / ' + issueMeta.kind);
    let merged = data;
    const startedAt = Date.now();
    const attempts = [];
    try {
      for (const tabName of tabs) {
        await switchDrawerTab(drawer, tabName);
        const beforeTabMissing = getMissingFieldsForData(merged);
        let tabAttempts = 1;
        merged = mergeData(merged, extractData(drawer, { forceSkuImage: tabName === L.productTab }));
        let afterTabMissing = getMissingFieldsForData(merged);
        if (afterTabMissing.length >= beforeTabMissing.length && afterTabMissing.some((field) => beforeTabMissing.includes(field))) {
          tabAttempts += 1;
          await wait(280);
          merged = mergeData(merged, extractData(drawer, { forceSkuImage: tabName === L.productTab }));
          afterTabMissing = getMissingFieldsForData(merged);
        }
        attempts.push({
          tab: tabName,
          count: tabAttempts,
          beforeMissing: beforeTabMissing,
          afterMissing: afterTabMissing,
        });
      }
      const afterMissing = getMissingFieldsForData(merged);
      const fixed = missing.filter((field) => !afterMissing.includes(field));
      if (fixed.length) {
        addLog('success', '\u4e8c\u6b21\u8bfb\u53d6\u5df2\u8865\u5230\u6570\u636e', data.sku + ' \u8865\u5230\uff1a' + fixed.join('\u3001'));
      } else {
        addLog('warn', '\u4e8c\u6b21\u8bfb\u53d6\u540e\u4ecd\u7f3a\u6570\u636e', data.sku + ' \u4ecd\u7f3a\uff1a' + afterMissing.join('\u3001'));
      }
      return attachMissingDiagnostic(merged, {
        status: fixed.length ? '\u90e8\u5206\u8865\u5230' : '\u4ecd\u7f3a',
        reason: fixed.length ? '\u4e8c\u6b21\u8bfb\u53d6\u6210\u529f\u8865\u5230\u90e8\u5206\u5b57\u6bb5' : '\u4e8c\u6b21\u8bfb\u53d6\u540e\u4ecd\u7f3a\u5b57\u6bb5',
        beforeMissing: missing,
        afterMissing,
        fixed,
        tabs,
        attempts,
        elapsedMs: Date.now() - startedAt,
      });
    } catch (error) {
      addLog('warn', '\u4e8c\u6b21\u8bfb\u53d6\u7f3a\u5931\u6570\u636e\u5931\u8d25', data.sku + ' ' + formatErrorMessage(error));
      return attachMissingDiagnostic(data, {
        status: '\u5931\u8d25',
        reason: formatErrorMessage(error),
        beforeMissing: missing,
        afterMissing: getMissingFieldsForData(data),
        fixed: [],
        tabs,
        attempts,
        elapsedMs: Date.now() - startedAt,
      });
    } finally {
      state.diagnosticRunning = false;
    }
  }

  function attachMissingDiagnostic(data, diagnostic) {
    return normalizeData({
      ...(data || {}),
      lastMissingDiagnostic: {
        status: String(diagnostic && diagnostic.status || '').slice(0, 40),
        reason: String(diagnostic && diagnostic.reason || '').slice(0, 160),
        beforeMissing: Array.isArray(diagnostic && diagnostic.beforeMissing) ? diagnostic.beforeMissing.slice(0, 20) : [],
        afterMissing: Array.isArray(diagnostic && diagnostic.afterMissing) ? diagnostic.afterMissing.slice(0, 20) : [],
        fixed: Array.isArray(diagnostic && diagnostic.fixed) ? diagnostic.fixed.slice(0, 20) : [],
        tabs: Array.isArray(diagnostic && diagnostic.tabs) ? diagnostic.tabs.slice(0, 8) : [],
        attempts: sanitizeDiagnosticAttempts(diagnostic && diagnostic.attempts),
        elapsedMs: Number(diagnostic && diagnostic.elapsedMs || 0) || 0,
        at: new Date().toLocaleString(),
      },
    });
  }

  function sanitizeDiagnosticAttempts(attempts) {
    return Array.isArray(attempts) ? attempts.slice(0, 8).map((item) => ({
      tab: String(item && item.tab || '').slice(0, 40),
      count: Number(item && item.count || 0) || 0,
      beforeMissing: Array.isArray(item && item.beforeMissing) ? item.beforeMissing.map((text) => String(text || '').slice(0, 80)).filter(Boolean).slice(0, 20) : [],
      afterMissing: Array.isArray(item && item.afterMissing) ? item.afterMissing.map((text) => String(text || '').slice(0, 80)).filter(Boolean).slice(0, 20) : [],
    })).filter((item) => item.tab) : [];
  }

  function getDiagnosticTabsForMissing(missing) {
    const tabs = [];
    const needMaterial = missing.some((field) => ['\u5305\u88c5\u5c3a\u5bf8', '\u5370\u5237\u5c3a\u5bf8', '\u51c0\u542b\u91cf'].includes(field));
    const needProduct = missing.some((field) => ['\u4ea7\u54c1\u5c3a\u5bf8', '\u6bdb\u91cd'].includes(field));
    const needProductAsset = missing.some((field) => ['SKU\u56fe'].includes(field));
    if (needMaterial) tabs.push(L.materialTab);
    if (needProduct) tabs.push(L.productTab);
    if (needProductAsset && !tabs.includes(L.productTab)) tabs.push(L.productTab);
    return tabs;
  }

  function requiresSkuImage(data) {
    return Boolean(data && data.projectStatus === '\u5df2\u5b8c\u6210');
  }

  function getProjectDrawerHeaderSku(drawer) {
    if (!drawer) return '';
    const header = drawer.querySelector('.taskInfo');
    if (!header || !isVisibleElement(header)) return '';
    const match = getVisibleText(header).match(/\u5546\u54c1\u7f16\u7801\s*[:\uff1a]\s*(SKU\d+)/i);
    return match ? match[1].toUpperCase() : '';
  }

  function getProjectDrawer() {
    if (state.openingProjectDetailSku) {
      const locked = getProjectDrawerForSku(state.openingProjectDetailSku);
      return locked || null;
    }
    const drawers = Array.from(document.querySelectorAll('.ant-drawer-open'))
      .filter(isVisibleElement)
      .filter((drawer) => {
        const text = getVisibleText(drawer);
        if (/\u67e5\u770b\u5546\u54c1/.test(text)) return false;
        return /\u67e5\u770b\u9879\u76ee\u8be6\u60c5/.test(text);
      });
    return drawers[drawers.length - 1] || null;
  }

  function extractData(drawer, options) {
    const opts = options || {};
    const text = getVisibleText(drawer);
    const activeTabText = getActiveTabText(drawer);
    const hasMaterialContent = /\u7269\u6599\u7f16\u7801[\s\S]*\u7269\u6599\u540d\u79f0[\s\S]*\u89c4\u683c\u578b\u53f7|\u5305\u88c5\u5c3a\u5bf8|\u5370\u5237\u5c3a\u5bf8|\u51c0\u542b\u91cf/.test(text);
    const hasProductContent = /PRODUCT\s*NAME|\u5546\u54c1\u540d\u79f0|\u4ea7\u54c1\u540d\u79f0|\u89c4\u683c\u4fe1\u606f|\u6bdb\u91cd|\u51c0\u542b\u91cf|\u6548\u679c\u56fe\u4fe1\u606f/.test(text);
    const seenMaterial = activeTabText === L.materialTab && hasMaterialContent;
    const seenProduct = activeTabText === L.productTab && hasProductContent;
    const plmIngredientText = seenProduct
      ? cleanExcelFieldValue(getFormValueByLooseLabel('\u6210\u5206', drawer) || getFormValueByLooseLabel('\u6210\u4efd', drawer))
      : '';
    const plmIngredientEnglishText = seenProduct
      ? cleanExcelFieldValue(getFormValueByLooseLabel('INGREDIENTS', drawer) || getFormValueByLooseLabel('INGREDIENT', drawer))
      : '';
    const projectStatus = extractProjectStatus(text);
    const packaging = seenMaterial ? extractPackaging(drawer) : emptyPackaging();
    const outer = extractOuterPackage(drawer);
    const inner = seenProduct ? extractInnerPackage(drawer) : { productNums: null };
    const food = seenMaterial ? extractFoodSemiFinished(drawer) : emptyFoodSemiFinished();
    const imageInfo = seenProduct && (projectStatus === '\u5df2\u5b8c\u6210' || opts.forceSkuImage) ? findDesignImageInfo(drawer) : { imageUrl: '', imageFallbackUrl: '', isSkuDesignImage: false };
    const tubeFields = extractTubeFields(drawer);
    const tubeSpec = packaging.isTubePrintMaterial
      ? findTubeSizeSpec([tubeFields.text, packaging.printRawText, packaging.printSizeText, packaging.printSizeLabel].filter(Boolean).join('\n'), tubeFields)
      : null;
    const isTubePrint = Boolean(tubeSpec);
    const singleBottle = Boolean(
      food.productNums && !packaging.packageNums && outer.packageNums &&
      !/\u7eb8\u76d2/.test(String(packaging.packageSizeLabel || '') + String(packaging.packageSizeText || ''))
    );
    const packageNums = singleBottle ? null : (packaging.packageNums || outer.packageNums);
    const hasInnerCard = hasInnerCardMark(packaging);
    const productNums = singleBottle ? outer.packageNums : (packageNums ? productNumsFromPackage(packageNums, hasInnerCard) : food.productNums);

    const brand = getProjectField(text, '\u54c1\u724c') || getFormValueByLabel('\u54c1\u724c', drawer);
    const developerText = extractDeveloperText(text);
    return {
      sku: getProjectDrawerHeaderSku(drawer),
      name: cleanName((text.match(/\u5546\u54c1\u540d\u79f0[:\uff1a]\s*([^\n]+)/) || [])[1] || ''),
      packageSizeText: packaging.packageSizeText || '',
      packageSizeLabel: packaging.packageSizeLabel || '',
      packageCode: packaging.packageCode || '',
      printSizeText: tubeSpec ? tubeSpec.printSizeText : (packaging.printSizeText || ''),
      printSizeLabel: tubeSpec ? '\u5370\u5237' : (packaging.printSizeLabel || ''),
      printCode: packaging.printCode || '',
      tubeSegmentText: tubeSpec ? tubeSpec.segmentText : '',
      tubeTailSealLengthValue: tubeSpec ? tubeSpec.tailSealText : '',
      tailSealLengthValue: tubeSpec ? tubeSpec.tailSealText : '',
      tubeDiameter: tubeSpec ? tubeSpec.diameter : '',
      tubeBody: tubeSpec ? tubeSpec.body : '',
      tubeSpecKey: tubeSpec ? tubeSpec.key : '',
      // Only promote the material to a tube after its segmented print size is recognized.
      // A generic printed-size row must remain a normal print material.
      isTubePrintMaterial: isTubePrint,
      packageNums,
      productNums: inner.productNums || productNums,
      plmProductNums: inner.productNums,
      bottleNums: singleBottle ? outer.packageNums : null,
      singleBottle,
      packageSource: packaging.packageSizeText || food.productNums || isTubePrint ? L.sourceMaterial : (outer.packageNums ? L.sourceOuter : ''),
      hasInnerCard,
      materialDimensionUnitIssues: seenMaterial ? packaging.materialDimensionUnitIssues : undefined,
      developerText,
      developerName: extractDeveloperName(developerText),
      brand,
      englishName: seenProduct ? cleanEnglishProductName(extractLineAfter(text, 'PRODUCT NAME'), brand) : '',
      plmIngredientText,
      plmIngredientEnglishText,
      plmIngredientParserVersion: PLM_INGREDIENT_CACHE_VERSION,
      plmIngredientCheckedAt: seenProduct ? Date.now() : 0,
      designType: getProjectLooseField(text, '\u8bbe\u8ba1\u7c7b\u578b'),
      artPriority: getProjectLooseField(text, '\u7f8e\u5de5\u5904\u7406\u4f18\u5148\u7ea7') || extractArtPriority(text),
      projectStatus,
      referenceUrl: extractReferenceUrl(text),
      designAssignedAt: getProjectLooseField(text, '\u8bbe\u8ba1\u5206\u914d\u65f6\u95f4'),
      developmentAssignedAt: getProjectLooseField(text, '\u5f00\u53d1\u5206\u914d\u65f6\u95f4'),
      netContent: normalizeNetContentValue(getBestNetContent(drawer) || food.netContent || packaging.netContent),
      grossWeight: getGrossWeightValue(drawer),
      skuImageUrl: imageInfo.isSkuDesignImage ? (imageInfo.imageUrl || '') : '',
      skuImageFallbackUrl: imageInfo.isSkuDesignImage ? (imageInfo.imageFallbackUrl || '') : '',
      skuImageSource: imageInfo.isSkuDesignImage ? 'effectImage' : '',
      seenMaterial,
      seenProduct,
      updatedAt: new Date().toLocaleString(),
      updatedAtMs: Date.now(),
    };
  }

  function mergeData(previous, next) {
    if (!previous) return normalizeData(next);
    const sameSku = previous.sku && next.sku && previous.sku === next.sku;
    if (!sameSku) return normalizeData(next);

    const merged = { ...previous };
    for (const key of Object.keys(next)) {
      const value = key === 'name' ? normalizeProductNameValue(next[key]) : next[key];
      if (isUsefulValue(value)) merged[key] = value;
    }
    if (next.seenMaterial) {
      const hasTubeSpec = Boolean(next.tubeSegmentText || next.tubeTailSealLengthValue || next.tailSealLengthValue || next.tubeDiameter || next.tubeBody || next.tubeSpecKey || next.isTubePrintMaterial);
      if (hasTubeSpec) {
        ['tubeSegmentText', 'tubeTailSealLengthValue', 'tailSealLengthValue', 'tubeDiameter', 'tubeBody', 'tubeSpecKey'].forEach((key) => {
          if (Object.prototype.hasOwnProperty.call(next, key)) merged[key] = next[key] || '';
        });
        if (Object.prototype.hasOwnProperty.call(next, 'isTubePrintMaterial')) merged.isTubePrintMaterial = Boolean(next.isTubePrintMaterial);
      } else {
        ['tubeSegmentText', 'tubeTailSealLengthValue', 'tailSealLengthValue', 'tubeDiameter', 'tubeBody', 'tubeSpecKey'].forEach((key) => {
          merged[key] = '';
        });
        merged.isTubePrintMaterial = false;
      }
    }
    if (next.seenProduct && (next.skuImageUrl || next.skuImageFallbackUrl)) {
      merged.skuImageUrl = next.skuImageUrl || merged.skuImageUrl || '';
      merged.skuImageFallbackUrl = next.skuImageFallbackUrl || merged.skuImageFallbackUrl || '';
      merged.skuImageSource = next.skuImageSource || merged.skuImageSource || 'effectImage';
    }
    if (next.seenProduct && Object.prototype.hasOwnProperty.call(next, 'plmProductNums')) {
      merged.plmProductNums = Array.isArray(next.plmProductNums) ? next.plmProductNums : null;
    }
    merged.seenMaterial = previous.seenMaterial || next.seenMaterial;
    merged.seenProduct = previous.seenProduct || next.seenProduct;
    return normalizeData(merged);
  }

  function hasMeaningfulDataChange(previous, next) {
    const ignored = new Set(['updatedAt', 'updatedAtMs', 'lastMissingDiagnostic', 'recentFieldChanges']);
    const before = {};
    const after = {};
    Object.keys(previous || {}).forEach((key) => {
      if (!ignored.has(key)) before[key] = getComparableDataFieldValue(key, previous[key]);
    });
    Object.keys(next || {}).forEach((key) => {
      if (!ignored.has(key)) after[key] = getComparableDataFieldValue(key, next[key]);
    });
    return JSON.stringify(before) !== JSON.stringify(after);
  }

  function isOrderInsensitiveTrackedField(key) {
    return key === 'printCode' || key === 'printSizeText';
  }

  function normalizeTrackedDataValue(key, value) {
    const text = key === 'name' ? normalizeProductNameValue(value) : compactText(value);
    if (!isOrderInsensitiveTrackedField(key) || !text) return text;
    return text.split(/\s*[;；]\s*/).map((item) => item.trim()).filter(Boolean).sort().join(';');
  }

  function getComparableDataFieldValue(key, value) {
    return isOrderInsensitiveTrackedField(key) ? normalizeTrackedDataValue(key, value) : value;
  }

  function trackedDataValuesEqual(key, before, after) {
    return normalizeTrackedDataValue(key, before) === normalizeTrackedDataValue(key, after);
  }

  function isManualOverrideField(key) {
    return MANUAL_OVERRIDE_FIELDS.includes(key);
  }

  function normalizeManualFieldOverrides(data) {
    const overrides = {};
    const explicit = data && data.manualFieldOverrides;
    if (explicit && typeof explicit === 'object' && !Array.isArray(explicit)) {
      MANUAL_OVERRIDE_FIELDS.forEach((key) => {
        if (Object.prototype.hasOwnProperty.call(explicit, key)) {
          overrides[key] = explicit[key] == null ? '' : String(explicit[key]).trim();
        }
      });
    }
    // Records created before 2.7.75 did not have an explicit override map.
    // Recover the last values that were saved from the manual calibration form.
    if (Array.isArray(data && data.recentFieldChanges)) {
      data.recentFieldChanges.forEach((change) => {
        if (!change || change.source !== '手动校准' || !isManualOverrideField(change.key) || Object.prototype.hasOwnProperty.call(overrides, change.key)) return;
        overrides[change.key] = change.after == null ? '' : String(change.after).trim();
      });
    }
    return overrides;
  }

  function applyManualFieldOverrides(data, overrides) {
    const next = { ...(data || {}), manualFieldOverrides: { ...(overrides || {}) } };
    const has = (key) => Object.prototype.hasOwnProperty.call(overrides || {}, key);
    const value = (key) => overrides[key] == null ? '' : String(overrides[key]).trim();
    MANUAL_OVERRIDE_FIELDS.forEach((key) => {
      if (has(key) && !/^(?:package|product)(?:Length|Width|Height)$/.test(key)) next[key] = value(key);
    });

    const applyDimensionGroup = (fields, numsKey, sizeKey) => {
      const hasDimensionOverride = fields.some((key) => has(key));
      if (!hasDimensionOverride) return;
      const nums = fields.map((key) => firstNumber(value(key)));
      if (!nums.every((item) => Number.isFinite(item) && item > 0)) return;
      next[numsKey] = nums;
      fields.forEach((key, index) => { next[key] = formatSingleDimension(nums[index]); });
      if (!has(sizeKey)) next[sizeKey] = nums.map(trimNumber).join('x') + 'cm';
    };

    applyDimensionGroup(['packageLength', 'packageWidth', 'packageHeight'], 'packageNums', 'packageSizeText');
    if (has('packageSizeText') && !['packageLength', 'packageWidth', 'packageHeight'].some((key) => has(key))) {
      const packageNums = parseDimension(value('packageSizeText'), 3);
      if (packageNums) {
        next.packageNums = packageNums;
        next.packageLength = formatDimensionPart(packageNums, 0);
        next.packageWidth = formatDimensionPart(packageNums, 1);
        next.packageHeight = formatDimensionPart(packageNums, 2);
      }
    }
    const productFields = ['productLength', 'productWidth', 'productHeight'];
    if (productFields.some((key) => has(key))) {
      const productNums = productFields.map((key) => firstNumber(value(key)));
      if (productNums.every((item) => Number.isFinite(item) && item > 0)) {
        next.productNums = productNums;
        next.plmProductNums = productNums;
        productFields.forEach((key, index) => { next[key] = formatSingleDimension(productNums[index]); });
        next.productSizeSource = 'manual';
        next.omitEstimatedProductSize = false;
      }
    }
    return next;
  }

  function normalizeData(data) {
    const safe = data || {};
    safe.name = normalizeProductNameValue(safe.name);
    const manualFieldOverrides = normalizeManualFieldOverrides(safe);
    migrateLabelValue(safe, 'packageSizeLabel', 'packageSizeText');
    migrateLabelValue(safe, 'printSizeLabel', 'printSizeText');
    stripKnownLabelPrefix(safe, 'packageSizeLabel', 'packageSizeText');
    stripKnownLabelPrefix(safe, 'printSizeLabel', 'printSizeText');
    safe.packageSizeLabel = cleanPackageDisplayLabel(safe.packageSizeLabel);
    const materialDimensionUnitIssues = normalizeMaterialDimensionUnitIssues(safe.materialDimensionUnitIssues, safe);
    const parsedPackageNums = materialDimensionUnitIssues.package ? null : parseDimension(safe.packageSizeText, 3);
    // Keep the dimension array aligned with the displayed text. Older cached
    // records may still carry only the first three values of a multi-page box.
    const detectedPackageNums = Array.isArray(safe.packageNums) &&
      (!parsedPackageNums || safe.packageNums.length === parsedPackageNums.length)
      ? safe.packageNums
      : parsedPackageNums;
    const classificationText = [safe.name, safe.netContent, safe.packageSizeLabel, safe.packageSizeText, safe.printSizeLabel, safe.printSizeText].filter(Boolean).join(' ');
    const singleBottle = Boolean(safe.singleBottle || (
      detectedPackageNums &&
      !/\u7eb8\u76d2/.test(String(safe.packageSizeLabel || '') + String(safe.packageSizeText || '')) &&
      /\u6807\u7b7e/.test(String(safe.printSizeLabel || '') + String(safe.printSizeText || '')) &&
      /\u98df\u54c1|\u80f6\u56ca|\u8f6f\u7cd6|capsules?|gumm(?:y|ies)|tablets?/i.test(classificationText)
    ));
    const bottleNums = singleBottle
      ? (Array.isArray(safe.bottleNums) ? safe.bottleNums : (detectedPackageNums || (Array.isArray(safe.productNums) ? safe.productNums : null)))
      : null;
    const packageNums = singleBottle ? null : detectedPackageNums;
    const hasInnerCard = hasInnerCardMark(safe);
    if (packageNums && packageNums.length >= 5 && !/\u591a\u9875/.test(String(safe.packageSizeLabel || ''))) {
      safe.packageSizeLabel = appendChineseRemark(safe.packageSizeLabel, '\u591a\u9875');
    }
    const plmProductNums = Array.isArray(safe.plmProductNums) && safe.plmProductNums.length >= 3
      ? safe.plmProductNums.slice(0, 3).map(Number)
      : null;
    const hasPlmProductSize = Boolean(plmProductNums && plmProductNums.every((value) => Number.isFinite(value) && value > 0));
    const omitEstimatedProductSize = !singleBottle && !hasPlmProductSize && isToyDimensionProduct(safe);
    const productNums = singleBottle
      ? bottleNums
      : (hasPlmProductSize
        ? plmProductNums
        : (!omitEstimatedProductSize
          ? (packageNums ? productNumsFromPackage(packageNums, hasInnerCard) : (Array.isArray(safe.productNums) ? safe.productNums : null))
          : null));
    const isTubePrint = isTubePrintData(safe);
    const copywriting = normalizeCopywritingRecord(safe.copywriting);
    const copywritingIngredientEnglish = normalizeIngredientLocantHyphens(String(safe.copywritingIngredientEnglish || copywriting && copywriting.cleanedIngredientEnglish || '').trim());
    const copywritingIngredientChinese = String(safe.copywritingIngredientChinese || copywriting && copywriting.cleanedIngredientChinese || '').trim();
    const plmIngredientText = String(safe.plmIngredientText || '').trim();
    const plmIngredientEnglishText = normalizeIngredientLocantHyphens(String(safe.plmIngredientEnglishText || '').trim());
    return applyManualFieldOverrides({
      ...safe,
      manualFieldOverrides,
      copywriting,
      copywritingIngredientEnglish,
      copywritingIngredientChinese,
      copywritingIngredientSplit: Boolean(safe.copywritingIngredientSplit || copywriting && copywriting.ingredientSplit),
      ingredientEnglish: normalizeIngredientLocantHyphens(safe.ingredientEnglish || copywritingIngredientEnglish || plmIngredientEnglishText),
      ingredientChinese: safe.ingredientChinese || copywritingIngredientChinese || plmIngredientText,
      hasInnerCard,
      singleBottle,
      bottleNums,
      isTubePrint,
      isTubePrintMaterial: Boolean(safe.isTubePrintMaterial),
      materialDimensionUnitIssues,
      packageNums,
      productNums,
      plmProductNums: hasPlmProductSize ? plmProductNums : null,
      productSizeSource: singleBottle ? 'product' : (hasPlmProductSize ? 'plm' : (productNums ? 'estimated' : 'none')),
      omitEstimatedProductSize,
      packageLength: formatDimensionPart(packageNums, 0),
      packageWidth: formatDimensionPart(packageNums, 1),
      packageHeight: formatDimensionPart(packageNums, 2),
      tubeSegmentText: isTubePrint ? (safe.tubeSegmentText || '') : '',
      tubeTailSealLengthValue: isTubePrint ? (safe.tubeTailSealLengthValue || '') : '',
      tailSealLengthValue: isTubePrint ? (safe.tailSealLengthValue || safe.tubeTailSealLengthValue || '') : '',
      productLength: isTubePrint ? (safe.tailSealLengthValue || safe.tubeTailSealLengthValue || '') : formatDimensionPart(productNums, 0),
      productWidth: formatDimensionPart(productNums, 1),
      productHeight: formatDimensionPart(productNums, 2),
    }, manualFieldOverrides);
  }

  function hasInnerCardMark(data) {
    if (!data) return false;
    return Boolean(data.hasInnerCard || /\u5185\u5361/.test(String(data.packageSizeLabel || '') + String(data.packageSizeText || '')));
  }

  function isDowmooBrand(data) {
    return Boolean(data && /\bDOWMOO\b/i.test(String(data.brand || '').trim()));
  }

  function isToyDimensionProduct(data) {
    if (isDowmooBrand(data)) return true;
    const text = [
      data && data.name,
      data && data.manualCategory,
      data && data.plmCategory,
      data && data.aiProductType,
      data && data.aiCategory,
      data && data.productType,
      data && data.category,
      data && data.departmentName,
    ].filter(Boolean).join(' ');
    if (/\btoys?\b|\bdolls?\b|玩具|公仔|玩偶|捏捏|积木|盲盒|史莱姆|解压/i.test(text)) return true;
    try {
      return getProductTypeForInsight(data, null) === '\u73a9\u5177';
    } catch (error) {
      return false;
    }
  }

  function shouldOmitToyProductSize(data) {
    return Boolean(data && (data.omitEstimatedProductSize || (isToyDimensionProduct(data) && data.productSizeSource !== 'plm' && !data.singleBottle)));
  }

  function migrateLabelValue(data, labelKey, valueKey) {
    if (!data || data[labelKey] || !data[valueKey]) return;
    const text = String(data[valueKey]);
    const index = text.indexOf('\uff1a');
    if (index <= 0) return;
    data[labelKey] = text.slice(0, index);
    data[valueKey] = text.slice(index + 1);
  }

  function stripKnownLabelPrefix(data, labelKey, valueKey) {
    if (!data || !data[labelKey] || !data[valueKey]) return;
    const prefix = data[labelKey] + '\uff1a';
    if (String(data[valueKey]).startsWith(prefix)) {
      data[valueKey] = String(data[valueKey]).slice(prefix.length);
    }
    data[valueKey] = stripGenericDimensionPrefixes(data[valueKey]);
  }

  function stripGenericDimensionPrefixes(value) {
    return String(value || '')
      .split(/\s*[\uff1b;]\s*/)
      .map((item) => item.replace(/^(?:\u5370\u5237|\u6807\u7b7e|\u5370\u5237\u5c3a\u5bf8|\u6807\u7b7e\u5c3a\u5bf8|\u5c3a\u5bf8)[:\uff1a]\s*(?=\d)/, ''))
      .filter(Boolean)
      .join('\uff1b');
  }

  function isUsefulValue(value) {
    if (value === '' || value === undefined || value === null || value === false) return false;
    if (Array.isArray(value) && value.length === 0) return false;
    return true;
  }

  function getProjectIdForMaterialApi(data) {
    const candidates = [data && data.projectRowId, data && data.projectId];
    const rowIdFromPage = data && data.sku ? findProjectRowIdBySku(data.sku) : '';
    const id = candidates.concat(rowIdFromPage).map((value) => String(value || '').trim()).find((value) => /^\d+$/.test(value));
    return id || '';
  }

  function getApiMaterialItems(payload) {
    const data = payload && (payload.data || payload.response && payload.response.data);
    if (Array.isArray(data)) return data;
    if (data && Array.isArray(data.pms)) return data.pms;
    if (data && data.data && Array.isArray(data.data.pms)) return data.data.pms;
    if (payload && Array.isArray(payload.pms)) return payload.pms;
    if (data && Array.isArray(data.list)) return data.list;
    return [];
  }

  function getApiListItems(payload) {
    const data = payload && payload.data !== undefined ? payload.data : payload && payload.response && payload.response.data;
    if (Array.isArray(data)) return data;
    if (data && Array.isArray(data.list)) return data.list;
    if (data && Array.isArray(data.rows)) return data.rows;
    if (data && Array.isArray(data.data)) return data.data;
    if (data && data.data && Array.isArray(data.data.list)) return data.data.list;
    if (payload && Array.isArray(payload.list)) return payload.list;
    if (payload && Array.isArray(payload.rows)) return payload.rows;
    return [];
  }

  function getApiProductListItems(payload) {
    const items = getApiListItems(payload);
    return items.length ? items : getApiMaterialItems(payload);
  }

  function getApiDetailAttributes(payload) {
    const root = payload && payload.data !== undefined ? payload.data : payload && payload.response && payload.response.data;
    const groups = Array.isArray(root)
      ? root
      : (root && Array.isArray(root.data) ? root.data
        : (root && root.data && Array.isArray(root.data.list) ? root.data.list
          : (root && Array.isArray(root.list) ? root.list : [])));
    const attrs = [];
    const addGroup = (group) => {
      if (!group || typeof group !== 'object') return;
      const candidates = [group.category_template_attrs, group.categoryTemplateAttrs, group.attrs];
      candidates.forEach((value) => {
        if (Array.isArray(value)) value.forEach((attr) => { if (attr && typeof attr === 'object') attrs.push(attr); });
      });
    };
    groups.forEach(addGroup);
    if (root && !Array.isArray(root)) addGroup(root);
    if (root && root.data && typeof root.data === 'object' && !Array.isArray(root.data)) addGroup(root.data);
    return attrs;
  }

  function getApiAttributeLanguages(attr) {
    if (!attr || typeof attr !== 'object') return [];
    if (Array.isArray(attr.attr_language_config_json)) return attr.attr_language_config_json;
    if (Array.isArray(attr.language_config)) return attr.language_config;
    if (Object.prototype.hasOwnProperty.call(attr, 'value')) return [{ language_id: attr.language_id || 1, value: attr.value }];
    return [];
  }

  function getApiAttributeValue(attr, languageId) {
    const languages = getApiAttributeLanguages(attr);
    const preferred = languages.find((item) => Number(item && item.language_id) === Number(languageId) && item.value !== undefined && item.value !== null)
      || languages.find((item) => item && item.value !== undefined && item.value !== null);
    return preferred ? preferred.value : '';
  }

  function getApiScalarText(value, depth) {
    if (value === null || value === undefined || depth > 4) return '';
    if (typeof value === 'string' || typeof value === 'number') return compactText(value);
    if (Array.isArray(value)) return value.map((item) => getApiScalarText(item, (depth || 0) + 1)).filter(Boolean).join('；');
    if (typeof value !== 'object') return '';
    for (const key of ['text', 'label', 'name', 'value', 'product_name', 'url', 'file_url', 'download_url', 'oss_url', 'path', 'file_path', 'file_save_full_path']) {
      if (value[key] !== undefined && value[key] !== null) {
        const text = getApiScalarText(value[key], (depth || 0) + 1);
        if (text) return text;
      }
    }
    return '';
  }

  function getApiAttributeLabel(attr) {
    if (!attr) return '';
    const archive = attr.archive_type_attr_data || attr.archiveTypeAttrData || {};
    return [attr.variable_name, attr.attr_name, attr.name, attr.title, attr.display_name, archive.name]
      .map((value) => compactText(value)).filter(Boolean).join(' ');
  }

  function getApiAttributeText(attrs, pattern, languageId) {
    const candidates = (Array.isArray(attrs) ? attrs : []).map((attr, index) => {
      const label = getApiAttributeLabel(attr);
      const match = label.match(pattern);
      return match ? { attr, index, score: match[0].length + (String(attr.variable_name || '').toLowerCase().includes('product_name') ? 20 : 0) } : null;
    }).filter(Boolean).sort((a, b) => b.score - a.score || a.index - b.index);
    for (const candidate of candidates) {
      const value = getApiScalarText(getApiAttributeValue(candidate.attr, languageId || 1), 0);
      if (value && !/^\d+(?:[.,;]\d+)*$/.test(value)) return value;
    }
    return '';
  }

  function getApiObjectFieldValue(objects, keys) {
    for (const object of objects || []) {
      if (!object || typeof object !== 'object') continue;
      for (const key of keys || []) {
        if (object[key] === undefined || object[key] === null || object[key] === '') continue;
        const value = getApiScalarText(object[key], 0);
        if (value) return value;
      }
    }
    return '';
  }

  function getApiAttributeRawValue(attrs, field) {
    const variableName = String(field && field.variableName || '').trim().toLowerCase();
    const labelPattern = field && field.labelPattern;
    const attr = (Array.isArray(attrs) ? attrs : []).find((item) => {
      const variable = String(item && item.variable_name || '').trim().toLowerCase();
      if (variableName && variable === variableName) return true;
      return Boolean(labelPattern && labelPattern.test(getApiAttributeLabel(item)));
    });
    return attr ? getApiScalarText(getApiAttributeValue(attr, 1), 0) : '';
  }

  function normalizeApiDimensionNumber(value, unit) {
    const text = compactText(value);
    if (!text || text === '--') return NaN;
    const number = Number(text) || firstNumber(text);
    if (!Number.isFinite(number) || number <= 0) return NaN;
    const unitText = String(unit || '') + ' ' + text;
    return /mm|毫米/i.test(unitText) ? number / 10 : number;
  }

  function getApiProductDimensionNums(objects, attrs, fields) {
    const nums = (fields || []).map((field) => {
      const objectValue = getApiObjectFieldValue(objects, [field.valueKey]);
      const objectUnit = getApiObjectFieldValue(objects, [field.unitKey]);
      const raw = objectValue || getApiAttributeRawValue(attrs, field);
      return normalizeApiDimensionNumber(raw, objectUnit);
    });
    return nums.length && nums.every((value) => Number.isFinite(value) && value > 0) ? nums : null;
  }

  function formatApiDimensionText(nums) {
    return Array.isArray(nums) && nums.length >= 3
      ? nums.slice(0, 3).map((value) => trimNumber(Number(value))).join('x') + 'cm'
      : '';
  }

  function getApiObjectAssetUrl(objects, keys) {
    for (const object of objects || []) {
      if (!object || typeof object !== 'object') continue;
      for (const key of keys || []) {
        const url = getApiAssetUrl(object[key], 0);
        if (url) return url;
      }
    }
    return '';
  }

  function getApiPayloadDataObject(payload) {
    const data = payload && payload.data !== undefined ? payload.data : payload && payload.response && payload.response.data;
    return data && typeof data === 'object' && !Array.isArray(data) ? data : {};
  }

  function getApiProductLanguageName(product, languageId) {
    const configs = product && (product.language_config || product.languageConfig);
    if (!Array.isArray(configs)) return '';
    const item = configs.find((entry) => Number(entry && entry.language_id) === Number(languageId))
      || configs.find((entry) => entry && entry.product_name);
    return compactText(item && (item.product_name || item.name || item.value));
  }

  function getApiLanguageConfigName(object, languageId) {
    const configs = object && (object.language_config || object.languageConfig);
    if (!Array.isArray(configs)) return '';
    const item = configs.find((entry) => Number(entry && entry.language_id) === Number(languageId))
      || configs.find((entry) => entry && entry.product_name);
    return compactText(item && (item.product_name || item.name || item.value));
  }

  function getApiEnglishProductName(values, brand) {
    for (const value of values || []) {
      const text = cleanEnglishProductName(value, brand);
      if (text && /[A-Za-z]/.test(text) && !/[\u3400-\u9fff]/.test(text)) return text;
    }
    return '';
  }

  function normalizeApiAssetUrl(value) {
    const text = compactText(value).replace(/&amp;/g, '&').replace(/\\\//g, '/');
    if (!text || /^(?:data:|javascript:)/i.test(text)) return '';
    if (/^https?:\/\//i.test(text)) return stripOssResizeParams(text);
    if (/^\/\//.test(text)) return stripOssResizeParams(location.protocol + text);
    if (/^(?:\/|[a-z0-9_-]+\/)/i.test(text) && !/^(?:filePic|assets)\//i.test(text)) return buildApiArchiveFileUrl(text);
    return '';
  }

  function getApiAssetUrl(value, depth) {
    if (value === null || value === undefined || depth > 4) return '';
    if (typeof value === 'string') return normalizeApiAssetUrl(value);
    if (Array.isArray(value)) {
      for (const item of value) {
        const url = getApiAssetUrl(item, (depth || 0) + 1);
        if (url) return url;
      }
      return '';
    }
    if (typeof value !== 'object') return '';
    for (const key of ['url', 'src', 'pic', 'image', 'file_url', 'download_url', 'oss_url', 'path', 'file_path', 'file_save_full_path', 'value']) {
      const url = getApiAssetUrl(value[key], (depth || 0) + 1);
      if (url) return url;
    }
    return '';
  }

  function getApiAttributeFileIds(attrs, pattern) {
    const ids = [];
    (Array.isArray(attrs) ? attrs : []).forEach((attr) => {
      if (!pattern.test(getApiAttributeLabel(attr))) return;
      getApiAttributeLanguages(attr).forEach((language) => collectApiCopywritingFileIds(language && language.value, ids));
      if (attr && attr.value !== undefined) collectApiCopywritingFileIds(attr.value, ids);
    });
    return ids.filter((id, index, list) => list.indexOf(id) === index);
  }

  async function fetchApiArchiveFileRecordsByIds(ids) {
    const normalizedIds = Array.from(new Set((ids || []).map((id) => Number(id)).filter((id) => Number.isFinite(id) && id > 0)));
    if (!normalizedIds.length) return [];
    let lastError = null;
    for (const endpoint of ['/api/ProjectFormData/GetArchiveFileVersionListByFileVersionId', '/api/Product/GetArchiveFileVersionListByFileVersionId']) {
      try {
        const payload = await fetchPlmApiJson(endpoint, { ids: normalizedIds });
        const records = getApiArchiveFileRecords(payload);
        if (records.length || endpoint.indexOf('/Product/') >= 0) return records;
      } catch (error) {
        lastError = error;
        if (/\b401\b|\b403\b/.test(formatErrorMessage(error))) throw error;
      }
    }
    if (lastError) throw lastError;
    return [];
  }

  function buildApiArchiveFileInfo(record) {
    const fileName = compactText(record && (record.file_name || record.file_original_name || record.original_file_name));
    const filePath = compactText(record && (record.file_path || record.file_save_full_path || record.oss_path || record.file_url || record.url));
    const fileId = String(record && (record.archive_file_version_id || record.file_version_id || record.id) || '');
    return {
      fileName,
      filePath,
      fileId,
      fileFormat: compactText(record && (record.file_format || record.format)),
      createdAt: compactText(record && (record.create_at || record.created_at || record.updated_at)),
      url: buildApiArchiveFileUrl(filePath),
    };
  }

  function getApiProductArchiveImageIds(attrs) {
    return getApiAttributeFileIds(attrs, /sku[_\s-]*pic|main[_\s-]*image|picture|产品图|主图/i);
  }

  function extractApiProductSnapshot(product, infoPayload, contentPayload) {
    const info = getApiPayloadDataObject(infoPayload);
    const attrs = getApiDetailAttributes(contentPayload);
    const objects = [product, info];
    const configs = product && (product.language_config || product.languageConfig);
    const outerDimensionFields = [
      { valueKey: 'long_outer_packaging', unitKey: 'long_outer_packaging_unit_name', variableName: 'long_outer_packaging', labelPattern: /长.*外包装/ },
      { valueKey: 'wide_outer_packaging', unitKey: 'wide_outer_packaging_unit_name', variableName: 'wide_outer_packaging', labelPattern: /宽.*外包装/ },
      { valueKey: 'high_outer_packaging', unitKey: 'high_outer_packaging_unit_name', variableName: 'high_outer_packaging', labelPattern: /高.*外包装/ },
    ];
    const innerDimensionFields = [
      { valueKey: 'long_inner_packing_materials', unitKey: 'long_inner_packing_materials_unit_name', variableName: 'long_inner_packing_materials', labelPattern: /长.*(?:内包材|内包装|产品)/ },
      { valueKey: 'wide_inner_packing_materials', unitKey: 'wide_inner_packing_materials_unit_name', variableName: 'wide_inner_packing_materials', labelPattern: /宽.*(?:内包材|内包装|产品)/ },
      { valueKey: 'high_inner_packing_materials', unitKey: 'high_inner_packing_materials_unit_name', variableName: 'high_inner_packing_materials', labelPattern: /高.*(?:内包材|内包装|产品)/ },
    ];
    const outerPackageNums = getApiProductDimensionNums(objects, attrs, outerDimensionFields);
    const innerPackageNums = getApiProductDimensionNums(objects, attrs, innerDimensionFields);
    const productCategory = getApiObjectFieldValue(objects, ['category_name', 'categoryName', 'product_category_name', 'productCategoryName'])
      || getApiAttributeText(attrs, /category|类目|品类/i, 1);
    const isToyProduct = isToyDimensionProduct({ plmCategory: productCategory, productType: productCategory });
    const brandValue = getApiObjectFieldValue(objects, ['brand_name', 'brandName', 'brand', 'brand_name_cn'])
      || getApiScalarText(product && product.brand, 0);
    const chineseName = getApiObjectFieldValue(objects, ['product_name', 'productName', 'name', 'name_cn', 'product_name_cn'])
      || getApiProductLanguageName(product, 1)
      || getApiLanguageConfigName(info, 1)
      || getApiAttributeText(attrs, /product[_\s-]*name|商品名称|产品名称|中文品名/i, 1);
    const englishName = getApiEnglishProductName([
      getApiObjectFieldValue(objects, ['product_name_en', 'productNameEn', 'english_name', 'name_en', 'productNameEnglish']),
      getApiProductLanguageName(product, 2),
      getApiLanguageConfigName(info, 2),
      getApiAttributeText(attrs, /product[_\s-]*name|product name|英文品名|英文名称/i, 2),
    ], brandValue);
    const rawProductSizeText = getApiObjectFieldValue(objects, ['product_size', 'productSize', 'product_size_text', 'size_text'])
      || getApiAttributeText(attrs, /product[_\s-]*size|产品尺寸|成品尺寸/i, 1);
    const parsedProductNums = parseDimension(rawProductSizeText, 3);
    const productNums = isToyProduct
      ? innerPackageNums
      : (innerPackageNums || parsedProductNums);
    const productSizeText = isToyProduct ? formatApiDimensionText(productNums) : rawProductSizeText;
    const directImage = getApiObjectAssetUrl(objects, ['sku_image_url', 'skuImageUrl', 'product_image_url', 'productImageUrl', 'pic', 'image', 'picture'])
      || getApiObjectFieldValue(objects, ['sku_image_url', 'skuImageUrl', 'product_image_url', 'productImageUrl', 'pic', 'image', 'picture'])
      || getApiAssetUrl(getApiAttributeValue((attrs || []).find((attr) => /sku[_\s-]*pic|main[_\s-]*image|picture|产品图|主图/i.test(getApiAttributeLabel(attr))), 1), 0);
    const referenceUrl = [
      getApiObjectFieldValue(objects, ['benchmark_link', 'benchmarkLink', 'benchmark_url', 'benchmarkUrl', 'reference_url', 'referenceUrl', 'alibaba_link', 'alibabaLink']),
      getApiAttributeText(attrs, /benchmark|reference|对标链接|参考链接|1688|阿里链接/i, 1),
    ].map((value) => String(value || '').match(/https?:\/\/[^\s]+/i)?.[0] || '').find(Boolean) || '';
    const packQty = getApiObjectFieldValue(objects, ['pack_qty', 'packQty', 'pack_count', 'packCount', 'carton_qty', 'cartonQty'])
      || getApiAttributeText(attrs, /pack[_\s-]*qty|pack[_\s-]*count|装箱数|装箱数量/i, 1);
    const purchasePrice = getApiObjectFieldValue(objects, ['purchase_price', 'purchasePrice', 'procurement_price', 'procurementPrice'])
      || getApiAttributeText(attrs, /purchase[_\s-]*price|procurement[_\s-]*price|采购价|采购价格/i, 1);
    const optional = {
      cartonSpec: getApiObjectFieldValue(objects, ['carton_spec', 'cartonSpec', 'outer_carton_spec', 'outerCartonSpec', 'carton_size', 'cartonSize'])
        || getApiAttributeText(attrs, /carton[_\s-]*(?:spec|size)|外箱规格|外箱尺寸/i, 1),
      packageMaterial: getApiObjectFieldValue(objects, ['package_material', 'packageMaterial', 'packaging_material', 'packagingMaterial'])
        || getApiAttributeText(attrs, /package[_\s-]*material|packaging[_\s-]*material|包装材质|包装材料/i, 1),
      leadTimeText: getApiObjectFieldValue(objects, ['lead_time', 'leadTime', 'delivery_text', 'deliveryText', 'delivery_note', 'deliveryNote'])
        || getApiAttributeText(attrs, /lead[_\s-]*time|delivery[_\s-]*(?:text|note)|交期|交货期/i, 1),
      alibabaLink: getApiObjectFieldValue(objects, ['alibaba_link', 'alibabaLink', '1688_link', '1688Link', 'alibaba_url', 'alibabaUrl'])
        || getApiAttributeText(attrs, /alibaba|1688|阿里链接/i, 1),
    };
    return {
      product,
      info,
      attrs,
      chineseName: normalizeProductNameValue(cleanExcelFieldValue(chineseName)),
      englishName,
      brand: compactText(brandValue),
      productType: productCategory || getApiObjectFieldValue(objects, ['product_type_name', 'productTypeName', 'product_type', 'productType']),
      plmCategory: productCategory,
      packageNums: outerPackageNums,
      outerPackageNums,
      outerPackageSizeText: formatApiDimensionText(outerPackageNums),
      innerPackageNums,
      productNums: productNums && productNums.length >= 3 ? productNums.slice(0, 3) : null,
      productSizeText: cleanExcelFieldValue(productSizeText),
      referenceUrl,
      packQty: normalizePackQty(packQty),
      purchasePrice: normalizeLedgerPurchasePrice(purchasePrice),
      productListImageUrl: normalizeApiAssetUrl(directImage),
      optional,
      imageFileIds: getApiProductArchiveImageIds(attrs),
      categoryId: String(product && product.category_id || info.category_id || ''),
      productId: String(product && (product.product_id || product.id) || info.product_id || ''),
      productVersionId: String(product && (product.product_version_id || product.product_main_id) || info.product_version_id || info.product_main_id || ''),
      languageConfig: Array.isArray(configs) ? configs : [],
    };
  }

  async function fetchApiProductSnapshot(data, options) {
    const sku = String(data && data.sku || '').trim().toUpperCase();
    if (!sku) return { found: false, sku };
    if (options && options.force) delete apiProductSnapshotCache[sku];
    if (!apiProductSnapshotCache[sku]) {
      const request = (async () => {
        const productPayload = await fetchPlmJson('/api/Product/GetProductList?page=1&pageSize=20&codes=' + encodeURIComponent(sku));
        const list = getApiProductListItems(productPayload);
        const product = list.find((item) => String(item && (item.product_code || item.productCode || item.code || '')).trim().toUpperCase() === sku) || list[0];
        if (!product) return { found: false, sku, reason: '产品列表未找到 SKU' };
        const productId = product.product_id || product.id;
        const productVersionId = product.product_version_id || product.product_main_id;
        const categoryId = product.category_id;
        let contentPayload = null;
        let contentError = '';
        let infoPayload = null;
        if (productId && productVersionId && categoryId) {
          try {
            contentPayload = await fetchPlmJson('/api/Product/GetDetailContent?is_edit=false&product_id=' + encodeURIComponent(productId) + '&product_version_id=' + encodeURIComponent(productVersionId) + '&category_id=' + encodeURIComponent(categoryId));
          } catch (error) {
            contentError = formatErrorMessage(error);
            addLog('warn', 'Excel 产品详情 API 读取失败', sku + ' | ' + formatErrorMessage(error));
          }
          try {
            infoPayload = await fetchPlmJson('/api/Product/GetDetailInfo?product_id=' + encodeURIComponent(productId) + '&product_version_id=' + encodeURIComponent(productVersionId));
          } catch (error) {
            addLog('info', 'Excel 产品基础信息 API 不可用，继续使用产品列表', sku + ' | ' + formatErrorMessage(error));
          }
        }
        return {
          found: true,
          sku,
          productId: String(productId || ''),
          productVersionId: String(productVersionId || ''),
          categoryId: String(categoryId || ''),
          contentPayload,
          contentError,
          infoPayload,
          ...extractApiProductSnapshot(product, infoPayload, contentPayload),
        };
      })();
      const task = request.finally(() => {
        if (apiProductSnapshotCache[sku] === task) delete apiProductSnapshotCache[sku];
      });
      apiProductSnapshotCache[sku] = task;
    }
    return apiProductSnapshotCache[sku];
  }

  async function fetchApiProjectSnapshot(data, options) {
    const sku = String(data && data.sku || '').trim().toUpperCase();
    if (!sku) return null;
    const existingId = [data && data.projectRowId, data && data.projectId].map((value) => String(value || '').trim()).find((value) => /^\d+$/.test(value));
    const existingReferenceUrl = String(data && (data.referenceUrl || data.benchmarkLink) || '').match(/https?:\/\/[^\s]+/i)?.[0] || '';
    if (existingId && existingReferenceUrl && !(options && options.force)) return { found: true, sku, projectId: existingId, referenceUrl: existingReferenceUrl };
    if (options && options.force) delete apiProjectSnapshotCache[sku];
    if (!apiProjectSnapshotCache[sku]) {
      const request = (async () => {
        let lastError = null;
        if (existingId) {
          try {
            const detailPayload = await fetchPlmJson('/api/ChemicalNew/GetProjectDetail?id=' + encodeURIComponent(existingId));
            const detailData = getApiPayloadDataObject(detailPayload);
            const project = detailData && detailData.project && typeof detailData.project === 'object' ? detailData.project : detailData;
            const referenceValue = getApiObjectFieldValue([project, detailData], ['reference_url', 'referenceUrl', 'benchmark_url', 'benchmarkUrl', 'benchmark_link', 'benchmarkLink', 'alibaba_link', 'alibabaLink']);
            const referenceUrl = String(referenceValue || '').match(/https?:\/\/[^\s]+/i)?.[0] || '';
            if (referenceUrl) {
              addLog('info', 'Excel 项目详情 API 已补到对标链接', sku + ' | projectId=' + existingId);
              return {
                found: true,
                sku,
                projectId: existingId,
                productId: String(project.product_id || project.productId || ''),
                productVersionId: String(project.product_main_id || project.product_version_id || project.productVersionId || ''),
                categoryId: String(project.category_id || project.categoryId || ''),
                name: compactText(project.product_name || project.productName || project.name),
                brand: compactText(project.brand_name || project.brandName || project.brand),
                referenceUrl,
                raw: project,
              };
            }
          } catch (error) {
            lastError = error;
          }
        }
        for (const endpoint of [
          '/api/ChemicalNewAll/GetList?page=1&pageSize=20&product_codes=' + encodeURIComponent(sku),
          '/api/ChemicalNewDesignTask/GetList?page=1&pageSize=20&product_codes=' + encodeURIComponent(sku),
        ]) {
          try {
            const payload = await fetchPlmJson(endpoint);
            const list = getApiListItems(payload);
            const row = list.find((item) => String(item && (item.product_code || item.productCode || item.code || '')).trim().toUpperCase() === sku);
            if (!row) continue;
            return {
              found: true,
              sku,
              projectId: String(row.id || row.project_id || row.chemical_id || row.project_row_id || row.projectRowId || ''),
              productId: String(row.product_id || ''),
              productVersionId: String(row.product_main_id || row.product_version_id || ''),
              categoryId: String(row.category_id || ''),
              name: compactText(row.product_name || row.productName || row.name),
              brand: compactText(row.brand_name || row.brandName || row.brand),
              referenceUrl: String(row.reference_url || row.referenceUrl || row.benchmark_url || row.benchmarkUrl || '').match(/https?:\/\/[^\s]+/i)?.[0] || '',
              raw: row,
            };
          } catch (error) {
            lastError = error;
          }
        }
        if (lastError) addLog('info', 'Excel 项目列表 API 未命中，继续使用产品/页面数据', sku + ' | ' + formatErrorMessage(lastError));
        if (existingId) return { found: true, sku, projectId: existingId };
        return null;
      })();
      const task = request.finally(() => {
        if (apiProjectSnapshotCache[sku] === task) delete apiProjectSnapshotCache[sku];
      });
      apiProjectSnapshotCache[sku] = task;
    }
    return apiProjectSnapshotCache[sku];
  }

  async function fetchApiDomesticThirdTierPrice(data, options) {
    const current = normalizeData(data || {});
    const sku = String(current.sku || '').trim().toUpperCase();
    let projectId = getProjectIdForMaterialApi(current);
    let project = null;
    if (!projectId && sku) {
      project = await fetchApiProjectSnapshot(current, options).catch(() => null);
      projectId = String(project && project.projectId || '').trim();
    }
    const snapshotPrice = extractApiDomesticThirdTierPrice([project, project && project.raw]);
    if (snapshotPrice) return snapshotPrice;
    if (!projectId || !/^\d+$/.test(projectId)) return '';

    if (apiProjectMaterialCache[projectId]) {
      const material = await apiProjectMaterialCache[projectId].catch(() => null);
      const materialPrice = extractApiDomesticThirdTierPrice([material, material && material.apiProject]);
      if (materialPrice) return materialPrice;
    }

    if (options && options.force) delete apiDomesticThirdTierPriceCache[projectId];
    if (!apiDomesticThirdTierPriceCache[projectId]) {
      const request = fetchPlmJson('/api/ChemicalNew/GetProjectDetail?id=' + encodeURIComponent(projectId))
        .then((payload) => extractApiDomesticThirdTierPrice([payload]))
        .catch((error) => {
          delete apiDomesticThirdTierPriceCache[projectId];
          throw error;
        });
      apiDomesticThirdTierPriceCache[projectId] = request;
    }
    return apiDomesticThirdTierPriceCache[projectId];
  }

  async function findApiIngredientPdfFromContent(contentPayload, sku) {
    const attrs = getApiDetailAttributes(contentPayload);
    const candidates = (Array.isArray(attrs) ? attrs : []).map((attr, index) => {
      const label = getApiAttributeLabel(attr);
      if (!/(?:成份|成分|ingredient|supplement\s*facts|material\s*list)/i.test(label)) return null;
      if (/(?:产品文案|product[_\s-]*description|copywriting|description)/i.test(label)) return null;
      const formats = getApiScalarText(attr && (attr.archive_type_attr_data || attr.archiveTypeAttrData), 0);
      const score = (/(?:成份|成分|supplement\s*facts)/i.test(label) ? 100 : 70) + (/(?:pdf)/i.test(formats) ? 30 : 0);
      return { attr, index, label, score };
    }).filter(Boolean).sort((a, b) => b.score - a.score || a.index - b.index);
    if (!candidates.length) return null;
    for (const candidate of candidates) {
      const direct = getApiAssetUrl(getApiAttributeValue(candidate.attr, 1), 0);
      if (direct && /(?:\.pdf(?:\?|$)|download|attachment)/i.test(direct)) {
        return { found: true, fileName: ((direct.match(/[^/?#]+\.pdf(?:[?#]|$)/i) || [])[0] || 'ingredient-' + sku + '.pdf').split(/[?#]/)[0], url: direct, source: 'plm-api' };
      }
      const ids = [];
      getApiAttributeLanguages(candidate.attr).forEach((language) => collectApiCopywritingFileIds(language && language.value, ids));
      if (candidate.attr && candidate.attr.value !== undefined) collectApiCopywritingFileIds(candidate.attr.value, ids);
      const records = await fetchApiArchiveFileRecordsByIds(ids);
      const files = records
        .filter((record) => record && !Number(record.is_invalid || 0))
        .map(buildApiArchiveFileInfo)
        .filter((file) => file.url && (/\.pdf$/i.test(file.fileName) || /pdf/i.test(file.fileFormat)));
      if (!files.length) continue;
      files.sort((a, b) => {
        const aSku = sku && new RegExp(escapeRegExp(sku), 'i').test(a.fileName) ? 1 : 0;
        const bSku = sku && new RegExp(escapeRegExp(sku), 'i').test(b.fileName) ? 1 : 0;
        return bSku - aSku || String(b.createdAt || '').localeCompare(String(a.createdAt || ''));
      });
      return { found: true, ...files[0], source: 'plm-api' };
    }
    return null;
  }

  async function fetchApiIngredientPdfFile(data, options) {
    const sku = String(data && data.sku || '').trim().toUpperCase();
    if (!sku) return { found: false, reason: '缺少 SKU' };
    if (options && options.force) delete apiIngredientFileCache[sku];
    if (!apiIngredientFileCache[sku]) {
      const request = (async () => {
        const snapshot = await fetchApiProductSnapshot({ sku }, options);
        if (snapshot && snapshot.contentError) throw new Error(snapshot.contentError);
        if (!snapshot || !snapshot.found || !snapshot.contentPayload) return { found: false, reason: '产品详情没有可读内容' };
        const file = await findApiIngredientPdfFromContent(snapshot.contentPayload, sku);
        return file || { found: false, reason: '产品详情没有成分表 PDF 附件' };
      })();
      const task = request.finally(() => {
        if (apiIngredientFileCache[sku] === task) delete apiIngredientFileCache[sku];
      });
      apiIngredientFileCache[sku] = task;
    }
    return apiIngredientFileCache[sku];
  }

  function getApiProductMetricValue(payload, variableName) {
    let result = '';
    const visit = (value) => {
      if (result || !value) return;
      if (Array.isArray(value)) {
        value.forEach(visit);
        return;
      }
      if (typeof value !== 'object') return;
      if (value.variable_name === variableName) {
        const languageValues = Array.isArray(value.attr_language_config_json) ? value.attr_language_config_json : [];
        const preferred = languageValues.find((item) => Number(item && item.language_id) === 1 && item.value != null)
          || languageValues.find((item) => item && item.value != null);
        const raw = preferred ? preferred.value : '';
        if (raw !== '' && raw != null) {
          const unit = Number(value.attr_display_unit_id) === 3 ? 'g' : (Number(value.attr_display_unit_id) === 4 ? 'ml' : '');
          const text = compactText(raw);
          result = unit && /^\d+(?:\.\d+)?$/.test(text) ? text + unit : text;
        }
        return;
      }
      Object.keys(value).forEach((key) => visit(value[key]));
    };
    visit(payload);
    return result;
  }

  function extractApiProductMetrics(payload) {
    const netContent = getApiProductMetricValue(payload, 'suttle');
    const grossWeight = getApiProductMetricValue(payload, 'rough_weight');
    return {
      ...(netContent ? { netContent } : {}),
      ...(grossWeight ? { grossWeight } : {}),
      ...(netContent || grossWeight ? { apiProductSource: 'plm-product-detail-content' } : {}),
    };
  }

  function extractApiDomesticThirdTierPrice(payloads) {
    const objects = [];
    (payloads || []).forEach((payload) => {
      if (payload && typeof payload === 'object' && !Array.isArray(payload)) objects.push(payload);
      const data = payload && payload.data;
      if (data && typeof data === 'object' && !Array.isArray(data)) {
        objects.push(data);
        if (data.project && typeof data.project === 'object') objects.push(data.project);
      }
      if (payload && payload.project && typeof payload.project === 'object') objects.push(payload.project);
      if (payload && payload.raw && typeof payload.raw === 'object') objects.push(payload.raw);
      objects.push(...getApiListItems(payload));
    });
    const raw = getApiObjectFieldValue(objects, [
      'domestic_third_tier_price', 'domesticThirdTierPrice',
      'domestic_three_price', 'domesticThreePrice',
    ]);
    return normalizeLedgerPurchasePrice(raw);
  }

  function collectApiCopywritingFileIds(value, ids) {
    if (value === null || value === undefined) return;
    if (Array.isArray(value)) {
      value.forEach((item) => collectApiCopywritingFileIds(item, ids));
      return;
    }
    if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
      ids.push(String(value));
      return;
    }
    if (typeof value === 'string' && /^\d+$/.test(value.trim())) {
      ids.push(value.trim());
      return;
    }
    if (typeof value !== 'object') return;
    ['archive_file_version_id', 'file_version_id', 'id'].forEach((key) => {
      if (value[key] !== undefined && value[key] !== null) collectApiCopywritingFileIds(value[key], ids);
    });
  }

  function extractApiCopywritingFileIds(payload) {
    const ids = [];
    const visit = (value) => {
      if (!value || typeof value !== 'object') return;
      if (Array.isArray(value)) {
        value.forEach(visit);
        return;
      }
      const variableName = String(value.variable_name || '').trim();
      const attrName = compactText(value.attr_name);
      if (variableName === 'product_description' || attrName === '\u4ea7\u54c1\u6587\u6848') {
        const languageValues = Array.isArray(value.attr_language_config_json) ? value.attr_language_config_json : [];
        const preferred = languageValues.find((item) => Number(item && item.language_id) === 1 && item.value != null)
          || languageValues.find((item) => item && item.value != null);
        collectApiCopywritingFileIds(preferred && preferred.value, ids);
        return;
      }
      Object.keys(value).forEach((key) => visit(value[key]));
    };
    visit(payload);
    return ids.filter((id, index, list) => list.indexOf(id) === index);
  }

  function getApiArchiveFileRecords(payload) {
    const data = payload && payload.data !== undefined ? payload.data : payload && payload.response && payload.response.data;
    if (Array.isArray(data)) return data;
    if (data && Array.isArray(data.list)) return data.list;
    if (payload && Array.isArray(payload.list)) return payload.list;
    return [];
  }

  function buildApiArchiveFileUrl(filePath) {
    const text = String(filePath || '').trim().replace(/^\/+/, '');
    if (!text) return '';
    if (/^https?:\/\//i.test(text)) return text;
    return PLM_ARCHIVE_OSS_ORIGIN + '/' + text;
  }

  async function fetchApiCopywritingFile(data, options) {
    const sku = String(data && data.sku || '').trim();
    if (!sku) return null;
    if (options && options.force) delete apiCopywritingFileCache[sku];
    if (!apiCopywritingFileCache[sku]) {
      const request = (async () => {
        addLog('info', '产品文案 API：开始读取产品关联', sku);
        const productPayload = await fetchPlmJson('/api/Product/GetProductList?page=1&pageSize=20&codes=' + encodeURIComponent(sku));
        const list = productPayload && productPayload.data && Array.isArray(productPayload.data.list) ? productPayload.data.list : [];
        const product = list.find((item) => String(item && (item.product_code || item.code) || '').trim() === sku) || list[0] || {};
        const productId = product.product_id;
        const productVersionId = product.product_version_id;
        const categoryId = product.category_id;
        if (!productId || !productVersionId || !categoryId) {
          throw new Error('产品列表缺少详情关联');
        }
        addLog('info', '产品文案 API：读取产品详情字段', sku + ' | product_id=' + productId + ' | category_id=' + categoryId);
        const contentPayload = await fetchPlmJson('/api/Product/GetDetailContent?is_edit=false&product_id=' + encodeURIComponent(productId) + '&product_version_id=' + encodeURIComponent(productVersionId) + '&category_id=' + encodeURIComponent(categoryId));
        const ids = extractApiCopywritingFileIds(contentPayload);
        if (!ids.length) {
          addLog('info', '产品文案 API：详情中没有关联 Word', sku);
          return { found: false, reason: '产品文案字段没有附件 ID' };
        }
        addLog('info', '产品文案 API：找到文案附件 ID', sku + ' | ids=' + ids.join(','));
        const filePayload = await fetchPlmApiJson('/api/Product/GetArchiveFileVersionListByFileVersionId', { ids: ids.map((id) => Number(id)) });
        const records = getApiArchiveFileRecords(filePayload)
          .filter((item) => item && !Number(item.is_invalid || 0))
          .filter((item) => /\.docx$/i.test(String(item.file_name || '')) || String(item.file_format || '').toLowerCase() === 'docx');
        const skuMatches = records.filter((item) => !sku || new RegExp(escapeRegExp(sku), 'i').test(String(item.file_name || '')));
        const candidates = skuMatches.length ? skuMatches : records;
        const file = candidates.sort((a, b) => {
          const aStamp = extractCopywritingFileTimestamp(a.file_name) || String(a.create_at || '');
          const bStamp = extractCopywritingFileTimestamp(b.file_name) || String(b.create_at || '');
          return bStamp.localeCompare(aStamp);
        })[0];
        if (!file) {
          addLog('info', '产品文案 API：附件列表中没有 docx', sku + ' | records=' + records.length);
          return { found: false, reason: '附件列表中没有 docx' };
        }
        const url = buildApiArchiveFileUrl(file.file_path);
        if (!url) throw new Error('文案附件缺少 file_path');
        const fileName = String(file.file_name || '').trim();
        addLog('info', '产品文案 API：命中文案 Word', sku + ' | ' + fileName + ' | ' + redactCopywritingUrl(url));
        return {
          found: true,
          fileName,
          filePath: String(file.file_path || ''),
          fileFormat: String(file.file_format || 'docx'),
          fileId: String(file.archive_file_version_id || ''),
          fileTimestamp: extractCopywritingFileTimestamp(fileName),
          createdAt: String(file.create_at || ''),
          url,
          source: 'plm-api',
        };
      })();
      const task = request.finally(() => {
        // Keep this cache only for concurrent callers.  A later 30-minute
        // refresh must query the current attachment metadata again.
        if (apiCopywritingFileCache[sku] === task) delete apiCopywritingFileCache[sku];
      });
      apiCopywritingFileCache[sku] = task;
    }
    return apiCopywritingFileCache[sku];
  }

  function getApiMaterialUnitIssue(item) {
    const propertyText = compactText(item && item.properties_value);
    const propertyIssue = detectMaterialDimensionUnitIssue(propertyText);
    if (propertyIssue) return propertyIssue;
    const unitText = [
      item && item.material_unit,
      item && item.material_unit_name,
      item && item.dimension_unit,
      item && item.unit,
      item && item.unit_name,
    ].map((value) => compactText(value)).find((value) => /^(?:m|米)$/i.test(value));
    if (!unitText) return null;
    const values = [item && item.material_length, item && item.material_width, item && item.material_height]
      .map((value) => firstNumber(value))
      .filter((value) => Number.isFinite(value) && value > 0);
    return { unit: 'm', raw: values.length >= 2 ? values.join('x') + 'm' : 'm' };
  }

  function getApiMaterialDimensions(item, count, preserveExtraDimensions) {
    if (getApiMaterialUnitIssue(item)) return null;
    // PLM occasionally returns stale or shifted material_length/width/height
    // values. The human-readable properties_value is the authoritative row
    // specification when it contains a complete dimension string.
    const propertyDimension = extractDimensionString(item && item.properties_value);
    const propertyParsed = parseDimension(propertyDimension, count);
    if (propertyParsed && propertyParsed.length >= count) {
      return preserveExtraDimensions ? propertyParsed : propertyParsed.slice(0, count);
    }
    const values = [item && item.material_length, item && item.material_width, item && item.material_height]
      .map((value) => {
        const text = String(value == null ? '' : value);
        const number = Number(text) || firstNumber(text);
        if (!Number.isFinite(number) || number <= 0) return 0;
        return /mm$/i.test(text.trim()) ? number / 10 : number;
      });
    if (values.slice(0, count).every((value) => value > 0)) return values.slice(0, count);
    const parsed = parseDimension(propertyDimension, count);
    return parsed && parsed.length >= count
      ? (preserveExtraDimensions ? parsed : parsed.slice(0, count))
      : null;
  }

  function formatApiMaterialDimensions(values) {
    return Array.isArray(values) && values.length >= 2
      ? values.map((value) => trimNumber(value)).join('x') + 'cm'
      : '';
  }

  function getApiMaterialDisplayName(value, keywordPattern) {
    const name = compactText(value);
    if (!name) return '';
    const match = name.match(keywordPattern);
    return match ? name.slice(match.index).trim() : name.trim();
  }

  function getApiPackageDisplayName(item) {
    return getPackageMaterialKind(item && item.name)
      || getPackageMaterialKind(item && item.category_name)
      || compactText(item && item.name)
      || compactText(item && item.category_name);
  }

  function getApiPrintDisplayName(item) {
    const pattern = /(标签|印刷软管|印刷尺寸|印刷管|印刷瓶|印刷乳液瓶|印刷)/;
    const raw = getApiMaterialDisplayName(item && item.name, pattern)
      || getApiMaterialDisplayName(item && item.category_name, pattern)
      || compactText(item && item.name)
      || compactText(item && item.category_name);
    return cleanPrintLabel(raw);
  }

  function isApiBoxCategory(value) {
    const category = compactText(value);
    return /包材/.test(category) && /纸盒|彩盒|纸箱|包装盒|外盒/.test(category);
  }

  function extractApiMaterialPackaging(payload) {
    const items = getApiMaterialItems(payload);
    const candidates = items.map((item, index) => {
      const name = compactText(item && item.name);
      const category = compactText(item && item.category_name);
      const supplier = compactText(item && (item.default_supplier_name || item.supplier_name));
      const text = name + ' ' + category + ' ' + supplier + ' ' + compactText(item && item.properties_value);
      const materialClassText = name + ' ' + category;
      const isPackagingCategory = /包材/.test(category);
      const isBoxCategory = isApiBoxCategory(category);
      // A product name such as “牙贴纸盒” contains the adjacent characters “贴纸”.
      // An explicit PLM box category is authoritative and must not be demoted to a label.
      const isPrintMaterial = !isBoxCategory && /标签|印刷|贴纸|不干胶|吊牌|印刷件/.test(materialClassText);
      const unitIssue = getApiMaterialUnitIssue(item);
      const dimensions = getApiMaterialDimensions(item, 3, true);
      let score = 0;
      if (/纸盒|彩盒|纸箱|包装盒|外盒|包装袋|铝箔袋|自封袋|袋子/.test(materialClassText)) score += 160;
      if (isPackagingCategory) score += 20;
      if (isPrintMaterial) score -= 100;
      if (dimensions && dimensions.length >= 3) score += 40;
      else if (unitIssue) score += 25;
      return { item, index, name, category, text, dimensions, unitIssue, score, isPackagingCategory, isPrintMaterial, displayName: getApiPackageDisplayName(item) };
    }).filter((item) => item.isPackagingCategory && !item.isPrintMaterial && item.score > 0 && ((item.dimensions && item.dimensions.length >= 3) || item.unitIssue))
      .sort((a, b) => b.score - a.score || a.index - b.index);
    const packageItem = candidates[0];
    const printItems = items.map((item, index) => {
      const name = compactText(item && item.name);
      const category = compactText(item && item.category_name);
      // Suppliers often contain "印刷" or "纸盒" (for example, "印刷有限公司-纸盒").
      // Use material name/category/properties for classification, otherwise a paper-box
      // supplier can make the paper box appear again in the label/printing group.
      const text = name + ' ' + category + ' ' + compactText(item && item.properties_value);
      const unitIssue = getApiMaterialUnitIssue(item);
      const dimensions = getApiMaterialDimensions(item, 2);
      return { item, index, name, category, text, dimensions, unitIssue, isBoxCategory: isApiBoxCategory(category), displayName: getApiPrintDisplayName(item) };
    }).filter((item) => (!packageItem || item.index !== packageItem.index)
      && !item.isBoxCategory
      && !/说明书|使用说明/.test(item.text)
      && /标签|印刷|贴纸|不干胶|吊牌|说明书|卡纸|印刷件/.test(item.text)
      && ((item.dimensions && item.dimensions.length >= 2) || item.unitIssue));
    const packageNums = packageItem && packageItem.dimensions ? packageItem.dimensions : null;
    const packageUnitIssue = packageItem && packageItem.unitIssue ? packageItem.unitIssue : null;
    return {
      packageSizeText: packageUnitIssue ? packageUnitIssue.raw : formatApiMaterialDimensions(packageNums),
      packageSizeLabel: packageItem ? packageItem.displayName : '',
      packageCode: packageItem ? String(packageItem.item.code || '') : '',
      packageNums,
      hasInnerCard: items.some((item) => /内卡/.test(compactText(item && item.name) + ' ' + compactText(item && item.category_name))),
      printSizeText: printItems.map((item) => item.unitIssue ? item.unitIssue.raw : formatApiMaterialDimensions(item.dimensions)).filter(Boolean).join('；'),
      printSizeLabel: printItems.map((item) => item.displayName).filter(Boolean).filter((value, index, arr) => arr.indexOf(value) === index).join('；'),
      printCode: printItems.map((item) => String(item.item.code || '')).filter(Boolean).join('；'),
      materialDimensionUnitIssues: {
        package: packageUnitIssue,
        print: (printItems.find((item) => item.unitIssue) || {}).unitIssue || null,
      },
      netContent: packageItem ? extractNetContentFromMaterial(packageItem.name + ' ' + compactText(packageItem.item.properties_value)) : '',
      apiMaterialSource: packageItem || printItems.length ? 'plm-project-pms' : '',
    };
  }

  function hasProductDetailPackage(data) {
    return Boolean(data
      && data.packageSource === 'plm-product-detail'
      && (isUsefulValue(data.packageSizeText) || isUsefulValue(data.packageNums)));
  }

  function resolveApiMaterialPackageSource(base, packaging) {
    const source = packaging || {};
    if (hasProductDetailPackage(base)) return 'plm-product-detail';
    if (isUsefulValue(source.packageSizeText) || isUsefulValue(source.packageNums)) return 'plm-project-pms';
    if (source.apiMaterialSource) return '';
    return base && base.packageSource ? base.packageSource : '';
  }

  function mergeApiPackagingData(base, packaging) {
    const merged = { ...(base || {}) };
    const source = packaging || {};
    const preserveProductDetailPackage = hasProductDetailPackage(merged);
    const packageKeys = new Set(['packageSizeText', 'packageSizeLabel', 'packageCode', 'packageNums']);
    [
      'packageSizeText', 'packageSizeLabel', 'packageCode', 'packageNums', 'hasInnerCard',
      'printSizeText', 'printSizeLabel', 'printCode', 'printRawText', 'isTubePrintMaterial',
      'netContent', 'grossWeight', 'apiMaterialSource',
    ].forEach((key) => {
      if (preserveProductDetailPackage && packageKeys.has(key)) return;
      if (isUsefulValue(source[key])) merged[key] = source[key];
    });
    const incomingPackage = ['packageSizeText', 'packageSizeLabel', 'packageCode', 'packageNums']
      .some((key) => isUsefulValue(source[key]));
    if (source.apiMaterialSource && !incomingPackage && !preserveProductDetailPackage) {
      merged.packageSizeText = '';
      merged.packageSizeLabel = '';
      merged.packageCode = '';
      merged.packageNums = null;
      merged.packageSource = '';
    }
    const currentIssues = normalizeMaterialDimensionUnitIssues(merged.materialDimensionUnitIssues, merged);
    const incomingIssues = normalizeMaterialDimensionUnitIssues(source.materialDimensionUnitIssues, source);
    merged.materialDimensionUnitIssues = {
      package: preserveProductDetailPackage
        ? currentIssues.package
        : (incomingIssues.package || (source.packageSizeText ? null : currentIssues.package)),
      print: incomingIssues.print || (source.printSizeText ? null : currentIssues.print),
    };
    return merged;
  }

  async function fetchPlmJson(url) {
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = controller ? window.setTimeout(() => controller.abort(), 15000) : 0;
    try {
      const baseRequestHeaders = {
        Accept: 'application/json, text/plain, */*',
        'x-app-code': 'PLM',
        'x-tenant-code': 'xy',
        'x-tenant-id': 'xy',
      };
      const capturedAuthHeaders = getPlmAuthHeaders();
      const requestFromPage = async (headers) => {
        const response = await fetch(url, {
          credentials: 'include',
          headers,
          signal: controller ? controller.signal : undefined,
        });
        if (!response.ok) throw new Error('HTTP ' + response.status);
        return response.json();
      };

      // PLM periodically rotates its page authorization header.  Prefer the
      // browser's live cookie session so a stale captured header cannot turn a
      // valid session into a 401.  The captured header remains a compatibility
      // fallback for endpoints that explicitly require it.
      let cookieRequestError = null;
      try {
        return await requestFromPage(baseRequestHeaders);
      } catch (error) {
        cookieRequestError = error;
      }

      let pageRequestError = cookieRequestError;
      if (Object.keys(capturedAuthHeaders).length) {
        try {
          return await requestFromPage({ ...baseRequestHeaders, ...capturedAuthHeaders });
        } catch (error) {
          pageRequestError = error;
        }
      }
      if (typeof GM_xmlhttpRequest === 'function' && /^\//.test(url)) {
        const gmResult = await new Promise((resolve, reject) => {
          let settled = false;
          const finish = (callback, value) => {
            if (settled) return;
            settled = true;
            callback(value);
          };
          GM_xmlhttpRequest({
            method: 'GET',
            url: new URL(url, window.location.origin).href,
            withCredentials: true,
            headers: { ...baseRequestHeaders, ...capturedAuthHeaders },
            timeout: 15000,
            onload: (response) => finish(resolve, response),
            onerror: () => finish(reject, new Error('网络请求失败')),
            ontimeout: () => finish(reject, new Error('请求超时')),
          });
        });
        if (!gmResult || gmResult.status < 200 || gmResult.status >= 300) {
          throw new Error('Cookie 会话 ' + formatErrorMessage(cookieRequestError) + '；页面授权 ' + formatErrorMessage(pageRequestError) + '；扩展请求 HTTP ' + (gmResult && gmResult.status || 0));
        }
        return JSON.parse(gmResult.responseText || '{}');
      }
      throw pageRequestError || new Error('PLM 页面请求失败');
    } finally {
      if (timer) window.clearTimeout(timer);
    }
  }

  function formatPlmApiMessage(value) {
    const scalar = getApiScalarText(value, 0);
    if (scalar) return scalar;
    if (value && typeof value === 'object') {
      try { return JSON.stringify(value); } catch (_) { return ''; }
    }
    return String(value || '').trim();
  }

  async function fetchPlmApiJson(url, body, options) {
    const opts = options || {};
    const timeout = Math.max(1000, Number(opts.timeout) || 30000);
    const request = {
      method: 'POST',
      url: new URL(url, window.location.origin).href,
      withCredentials: true,
      headers: {
        Accept: 'application/json, text/plain, */*',
        'Content-Type': 'application/json;charset=UTF-8',
        'x-app-code': 'PLM',
        'x-tenant-code': 'xy',
        'x-tenant-id': 'xy',
        ...getPlmAuthHeaders(),
      },
      data: JSON.stringify(body || {}),
      timeout,
    };
    const response = typeof GM_xmlhttpRequest === 'function'
      ? await new Promise((resolve, reject) => GM_xmlhttpRequest({ ...request, onload: resolve, onerror: () => reject(new Error('网络请求失败')), ontimeout: () => reject(new Error('请求超时')) }))
      : await fetchWithTimeout(request.url, timeout, { method: 'POST', credentials: 'include', headers: request.headers, body: request.data });
    const status = Number(response && response.status || 0);
    const text = response && typeof response.responseText === 'string' ? response.responseText : await response.text();
    if (status < 200 || status >= 300) throw new Error('HTTP ' + status);
    const payload = JSON.parse(text || '{}');
    if (payload && payload.success === false) throw new Error(formatPlmApiMessage(payload.msg) || formatPlmApiMessage(payload.message) || 'PLM API 返回失败');
    return payload;
  }

  async function fetchApiMaterialPackaging(data, options) {
    const sku = String(data && data.sku || '');
    const projectId = getProjectIdForMaterialApi(data);
    if (!projectId || !window.fetch) {
      if (sku) {
        addLog('warn', '详情自动读取物料接口跳过', sku + ' | 未找到项目 ID');
        setApiReadStatus(sku, 'error', '未找到项目 ID');
      }
      return emptyPackaging();
    }
    setApiReadStatus(sku, 'loading', '正在读取 PLM 数据');
    if (options && options.force) delete apiProjectMaterialCache[projectId];
    if (!apiProjectMaterialCache[projectId]) {
      addLog('info', '详情自动读取 PLM 物料接口', sku + ' | projectId=' + projectId);
      apiProjectMaterialCache[projectId] = fetchPlmJson('/api/ChemicalNew/GetProjectDetail?id=' + encodeURIComponent(projectId))
        .then((payload) => ({
          result: extractApiMaterialPackaging(payload),
          project: payload && payload.data && payload.data.project || {},
        }))
        .catch((error) => {
          addLog('warn', 'PLM 项目物料读取失败，继续读取产品接口', sku + ' | ' + formatErrorMessage(error));
          return { result: emptyPackaging(), project: {} };
        })
        .then(({ result, project }) => {
          const productId = project.product_id;
          const productVersionId = project.product_main_id;
          const productSku = sku || String(project.product_code || '');
          const projectResult = { ...result, apiProject: project };
          return fetchPlmJson('/api/Product/GetProductList?page=1&pageSize=20&codes=' + encodeURIComponent(productSku))
            .then((productPayload) => {
              const list = getApiProductListItems(productPayload);
              const product = list.find((item) => String(item && (item.product_code || item.productCode || item.code || '')).trim().toUpperCase() === String(productSku || '').trim().toUpperCase()) || list[0] || {};
              const categoryId = product.category_id;
              if (!categoryId || (!(product.product_id || productId)) || (!(product.product_version_id || productVersionId))) {
                addLog('info', 'PLM 产品列表读取完成但缺少详情关联', productSku + ' | 保留已读取物料结果');
                return projectResult;
              }
              return fetchPlmJson('/api/Product/GetDetailContent?is_edit=false&product_id=' + encodeURIComponent(product.product_id || productId) + '&product_version_id=' + encodeURIComponent(product.product_version_id || productVersionId) + '&category_id=' + encodeURIComponent(categoryId))
                .then((contentPayload) => ({ ...projectResult, ...extractApiProductMetrics(contentPayload) }))
                .catch((error) => {
                  addLog('warn', 'PLM 产品详情字段读取失败', productSku + ' | ' + formatErrorMessage(error));
                  return projectResult;
                });
            })
            .catch((error) => {
              addLog('warn', 'PLM 产品列表读取失败', productSku + ' | ' + formatErrorMessage(error));
              return projectResult;
            });
        })
        .then((result) => {
          addLog('info', 'PLM 接口读取完成', sku + ' | 纸盒=' + (result.packageSizeText || '无') + ' | 标签/印刷=' + (result.printSizeText || '无') + ' | 净含量=' + (result.netContent || '无') + ' | 毛重=' + (result.grossWeight || '无'));
          setApiReadStatus(sku, 'success', hasUsableApiData(result) ? 'PLM 数据读取完成' : 'PLM 读取完成，暂无可用字段');
          return result;
        })
        .catch((error) => {
          const detail = /HTTP 401/.test(formatErrorMessage(error))
            ? formatErrorMessage(error) + ' | 请刷新 PLM 页面后重试，或检查当前账号项目权限'
            : formatErrorMessage(error);
          addLog('warn', 'PLM 物料接口读取失败', sku + ' | ' + detail);
          setApiReadStatus(sku, 'error', 'PLM 读取失败');
          return emptyPackaging();
        });
    }
    return apiProjectMaterialCache[projectId].then((result) => {
      if (state.apiReadStatus && state.apiReadStatus.sku === sku && state.apiReadStatus.phase === 'loading') {
        setApiReadStatus(sku, 'success', hasUsableApiData(result) ? 'PLM 数据读取完成' : 'PLM 读取完成，暂无可用字段');
      }
      return result;
    });
  }

  async function refreshMaterialFromApiWithoutDrawer(sku, seedData) {
    if (!state.settings.collectionEnabled || !sku) return;
    const indexed = state.index.find((entry) => entry && entry.sku === sku);
    const current = normalizeData(seedData || loadData(sku) || (state.data && state.data.sku === sku ? state.data : null) || indexed || { sku });
    setApiReadStatus(sku, 'loading', '正在读取 PLM 数据');
    try {
      const apiResult = await fetchApiExcelData(current, { force: true });
      if (!apiResult || !apiResult.found || !apiResult.data) {
        setApiReadStatus(sku, 'error', '未找到 PLM 数据');
        if (state.selectedSku === sku) showToast('PLM 未找到可更新数据', { quiet: true });
        return;
      }
      const merged = normalizeData({
        ...current,
        ...apiResult.data,
        updatedAt: new Date().toLocaleString(),
        updatedAtMs: Date.now(),
      });
      saveData(sku, merged, { changeSource: 'PLM 接口' });
      setApiReadStatus(sku, 'success', 'PLM 数据读取完成');
      if (state.selectedSku === sku) {
        state.data = merged;
        renderShell('已刷新 PLM 数据');
        showApiDataChangeNotice(sku, current, merged);
      }
    } catch (error) {
      setApiReadStatus(sku, 'error', 'PLM 读取失败');
      addLog('warn', '搜索 SKU 自动 API 刷新失败', sku + ' | ' + formatErrorMessage(error));
      if (state.selectedSku === sku) showToast('PLM 刷新失败，请稍后重试', { quiet: true });
    }
  }

  async function fetchApiExcelData(data, options) {
    const current = normalizeData(data || {});
    const sku = String(current.sku || '').trim().toUpperCase();
    if (!sku) return null;
    const opts = options || {};
    let product = null;
    let project = null;
    try {
      product = await fetchApiProductSnapshot({ sku }, opts);
    } catch (error) {
      addLog('warn', 'Excel 产品 API 补全失败，继续使用页面读取', sku + ' | ' + formatErrorMessage(error));
    }
    try {
      project = await fetchApiProjectSnapshot(current, opts);
    } catch (error) {
      addLog('info', 'Excel 项目 API 补全失败，继续使用页面读取', sku + ' | ' + formatErrorMessage(error));
    }
    const productId = String(product && (product.productId || product.product && (product.product.product_id || product.product.id)) || '');
    const productVersionId = String(product && (product.productVersionId || product.product && (product.product.product_version_id || product.product.product_main_id)) || '');
    const categoryId = String(product && (product.categoryId || product.category_id) || project && project.categoryId || '');
    const projectId = String(project && project.projectId || current.projectRowId || current.projectId || '').trim();
    const optional = product && product.optional || {};
    const optionalSeed = Object.keys(optional).reduce((result, key) => {
      if (isUsefulValue(optional[key])) result[key] = optional[key];
      return result;
    }, {});
    const productMetrics = product && product.contentPayload ? extractApiProductMetrics(product.contentPayload) : {};
    let imageUrl = product && product.productListImageUrl || '';
    let imageFallbackUrl = imageUrl;
    if (!imageUrl && product && product.imageFileIds && product.imageFileIds.length) {
      try {
        const records = await fetchApiArchiveFileRecordsByIds(product.imageFileIds);
        const image = records.map(buildApiArchiveFileInfo)
          .filter((file) => file.url && (/\.(?:jpe?g|png|webp|bmp|gif)$/i.test(file.fileName) || /(?:jpe?g|png|webp|bmp|gif)/i.test(file.fileFormat)))
          .sort((a, b) => {
            const aSku = sku && new RegExp(escapeRegExp(sku), 'i').test(a.fileName) ? 1 : 0;
            const bSku = sku && new RegExp(escapeRegExp(sku), 'i').test(b.fileName) ? 1 : 0;
            return bSku - aSku || String(b.createdAt || '').localeCompare(String(a.createdAt || ''));
          })[0];
        if (image) {
          imageUrl = image.url;
          imageFallbackUrl = image.url;
        }
      } catch (error) {
        addLog('info', 'Excel 产品图片附件 API 读取失败，继续使用页面图片', sku + ' | ' + formatErrorMessage(error));
      }
    }
    const apiProductFound = Boolean(product && product.found);
    const apiProductCategoryData = {
      ...current,
      plmCategory: product && product.plmCategory || current.plmCategory || '',
      productType: product && product.productType || current.productType || '',
    };
    const toyApiPackageNums = apiProductFound && isToyDimensionProduct(apiProductCategoryData) && product.outerPackageNums
      ? product.outerPackageNums
      : null;
    const seed = normalizeData({
      ...current,
      sku,
      projectRowId: projectId || current.projectRowId || '',
      projectId: projectId || current.projectId || '',
      projectProductId: productId || current.projectProductId || '',
      productVersionId: productVersionId || current.productVersionId || '',
      name: normalizeProductNameValue(product && product.chineseName) || normalizeProductNameValue(project && project.name) || normalizeProductNameValue(current.name),
      brand: product && product.brand || project && project.brand || current.brand || '',
      englishName: product && product.englishName || current.englishName || '',
      productType: product && product.productType || current.productType || '',
      plmCategory: product && product.plmCategory || current.plmCategory || '',
      packageNums: toyApiPackageNums || current.packageNums || null,
      packageSizeText: product && product.outerPackageSizeText && toyApiPackageNums
        ? product.outerPackageSizeText
        : current.packageSizeText || '',
      referenceUrl: product && product.referenceUrl || project && project.referenceUrl || current.referenceUrl || '',
      benchmarkLink: product && product.referenceUrl || project && project.referenceUrl || current.benchmarkLink || '',
      packQty: product && product.packQty || current.packQty || '',
      purchasePrice: current.purchasePrice || '',
      netContent: productMetrics.netContent || current.netContent || '',
      grossWeight: productMetrics.grossWeight || current.grossWeight || '',
      plmProductNums: apiProductFound ? (product.productNums || null) : (current.plmProductNums || null),
      productListImageUrl: imageUrl || current.productListImageUrl || '',
      productListImageFallbackUrl: imageFallbackUrl || current.productListImageFallbackUrl || '',
      skuImageUrl: imageUrl || current.skuImageUrl || '',
      skuImageFallbackUrl: imageFallbackUrl || current.skuImageFallbackUrl || '',
      skuImageSource: imageUrl ? 'productListImage' : current.skuImageSource || '',
      ...optionalSeed,
    });
    let material = emptyPackaging();
    if (getProjectIdForMaterialApi(seed)) {
      try {
        material = await fetchApiMaterialPackaging(seed, { force: Boolean(opts.force) });
      } catch (error) {
        addLog('warn', 'Excel 物料 API 补全失败，继续使用页面读取', sku + ' | ' + formatErrorMessage(error));
      }
    }
    const projectDetail = material && material.apiProject || {};
    const projectObjects = [project, project && project.raw, projectDetail];
    // Only the explicitly named domestic third-tier field is trusted for Excel.
    // Procurement/reference prices from other product endpoints have different semantics.
    const apiPurchasePrice = extractApiDomesticThirdTierPrice(projectObjects);
    const projectReferenceUrl = getApiObjectFieldValue(projectObjects, ['reference_url', 'referenceUrl', 'benchmark_url', 'benchmarkUrl', 'benchmark_link', 'benchmarkLink', 'alibaba_link', 'alibabaLink'])
      .match(/https?:\/\/[^\s]+/i)?.[0] || '';
    const projectPackQty = normalizePackQty(getApiObjectFieldValue(projectObjects, ['pack_qty', 'packQty', 'pack_count', 'packCount', 'carton_qty', 'cartonQty']));
    const merged = normalizeData({
      ...mergeApiPackagingData(seed, material),
      ...(toyApiPackageNums ? {
        packageNums: toyApiPackageNums,
        packageSizeText: product.outerPackageSizeText || formatApiDimensionText(toyApiPackageNums),
      } : {}),
      packageSource: toyApiPackageNums
        ? 'plm-product-detail'
        : resolveApiMaterialPackageSource(seed, material),
      referenceUrl: seed.referenceUrl || projectReferenceUrl || current.referenceUrl || '',
      benchmarkLink: seed.benchmarkLink || projectReferenceUrl || current.benchmarkLink || '',
      packQty: seed.packQty || projectPackQty || current.packQty || '',
      purchasePrice: seed.purchasePrice || apiPurchasePrice || current.purchasePrice || '',
      purchasePriceSource: seed.purchasePrice
        ? (seed.purchasePriceSource || current.purchasePriceSource || '')
        : (apiPurchasePrice ? 'plm-api-domestic-third-tier' : (current.purchasePriceSource || '')),
      purchasePriceUpdatedAt: seed.purchasePrice
        ? (seed.purchasePriceUpdatedAt || current.purchasePriceUpdatedAt || '')
        : (apiPurchasePrice ? new Date().toLocaleString() : (current.purchasePriceUpdatedAt || '')),
      updatedAt: new Date().toLocaleString(),
      updatedAtMs: Date.now(),
    });
    if (apiPurchasePrice && !normalizeLedgerPurchasePrice(current.purchasePrice)) {
      addLog('success', 'Excel 已读取国内三档价格', sku + ' | ' + apiPurchasePrice);
    }
    let ingredientFile = null;
    if (product && product.contentPayload) {
      try {
        ingredientFile = await findApiIngredientPdfFromContent(product.contentPayload, sku);
      } catch (error) {
        addLog('info', 'Excel 成分表附件 API 读取失败，继续使用页面附件', sku + ' | ' + formatErrorMessage(error));
      }
    }
    const apiDataAvailable = Boolean(product && product.found || project && project.found || hasUsableApiData(material));
    return {
      found: apiDataAvailable,
      data: merged,
      product,
      project,
      ingredientFile,
      englishName: product && product.englishName || merged.englishName || '',
      chineseName: product && product.chineseName || merged.name || '',
      benchmarkLink: merged.benchmarkLink || merged.referenceUrl || '',
      imageUrl,
      imageFallbackUrl,
      isSkuDesignImage: Boolean(imageUrl && isStrictDesignImageUrl(imageUrl)),
      skuImageUrl: imageUrl,
      skuImageFallbackUrl: imageFallbackUrl,
      skuImageSource: imageUrl ? 'productListImage' : '',
      productId,
      productVersionId,
      categoryId,
      projectId,
    };
  }

  function extractPackaging(root) {
    const rows = getMaterialRows(root);
    const packageRows = rows
      .map((row, index) => ({ row, index, score: getPackageMaterialRowScore(row) }))
      .filter((item) => item.score > 0)
      .sort((a, b) => b.score - a.score || a.index - b.index)
      .map((item) => item.row);
    const printRows = rows.filter(isPrintMaterialRow);
    const packageRow = packageRows[0] || '';
    const packageUnitIssue = detectMaterialDimensionUnitIssue(packageRow);
    const packageDim = packageUnitIssue ? '' : extractDimensionString(packageRow);
    const packageRawDim = packageUnitIssue ? packageUnitIssue.raw : '';
    const packageNums = packageUnitIssue ? null : parseDimension(packageDim, 3);
    let packageName = getPackageMaterialKind(extractMaterialName(packageRow)) || getMaterialDisplayName(packageRow, /(\u7eb8\u76d2|\u5370\u5237\u81ea\u7acb\u888b|\u5370\u5237\u888b|\u5305\u88c5\u888b|\u94dd\u7b94\u888b|\u81ea\u5c01\u888b|\u888b\u5b50)/);
    if (packageNums && packageNums.length >= 5 && !/\u591a\u9875/.test(packageName + packageRow)) {
      packageName = appendChineseRemark(packageName, '\u591a\u9875');
    }
    const printUnitIssues = [];
    const printItems = printRows.map((row) => {
      const unitIssue = detectMaterialDimensionUnitIssue(row);
      if (unitIssue) {
        printUnitIssues.push(unitIssue);
        return unitIssue.raw;
      }
      const dims = extractNamedDimensionStrings(row);
      if (!dims.length) return '';
      return dims.join('\uff1b');
    }).filter(Boolean);

    return {
      packageSizeText: packageDim || packageRawDim,
      packageSizeLabel: packageName || '',
      packageCode: extractMaterialCode(packageRow),
      packageNums,
      hasInnerCard: /\u5185\u5361/.test(packageRow),
      printSizeText: printItems.join('\uff1b'),
      printSizeLabel: getCombinedPrintLabel(printRows),
      printCode: printRows.map(extractMaterialCode).filter(Boolean).join('\uff1b'),
      materialDimensionUnitIssues: {
        package: packageUnitIssue,
        print: printUnitIssues[0] || null,
      },
      isTubePrintMaterial: printRows.some(isTubePrintRow),
      printRawText: printRows.join('\uff1b').slice(0, 1000),
      netContent: extractNetContentFromMaterial(packageRow) || extractNetContentFromMaterial(printRows[0] || ''),
    };
  }

  function isPrintMaterialRow(row) {
    const text = String(row || '');
    if (/说明书|使用说明/.test(text)) return false;
    const excludedPackaging = /(\u8bf4\u660e\u4e66|\u5370\u5237\u81ea\u7acb\u888b|\u5370\u5237\u888b|\u5305\u88c5\u888b|\u94dd\u7b94\u888b|\u81ea\u5c01\u888b|\u888b\u5b50)/.test(text);
    const hasExplicitPrintSize = /\u5370\u5237\u5c3a\u5bf8\s*[:\uff1a]?\s*\d/i.test(text) && hasPrintDimensionText(text);
    // PLM categories are sometimes entered as "printed bag" even when the material description clearly identifies a tube.
    // A real printed bag with an explicitly labeled print size is both packaging and a printable material.
    if (excludedPackaging && !isTubePrintRow(text) && !hasExplicitPrintSize) return false;
    return (/\u5305\u6750/.test(text) && /(\u6807\u7b7e|\u5370\u5237\u8f6f\u7ba1|\u5370\u5237\u5c3a\u5bf8|\u5370\u5237\u7ba1|\u5370\u5237\u74f6|\u5370\u5237\u4e73\u6db2\u74f6)/.test(text))
      || (/\u5305\u6750/.test(text) && /\u5370\u5237/.test(text) && hasPrintDimensionText(text))
      || (/\u5370\u5237(?:\u74f6|\u7ba1|\u8f6f\u7ba1|\u4e73\u6db2\u74f6)/.test(text) && hasPrintDimensionText(text));
  }

  function getProjectField(text, fieldName) {
    const escaped = escapeRegExp(fieldName);
    const stop = /(\u9879\u76ee\u7f16\u7801|\u9700\u6c42\u7f16\u7801|\u5546\u54c1\u540d\u79f0|\u5546\u54c1\u7f16\u7801|\u7f8e\u5de5\u5904\u7406\u4f18\u5148\u7ea7|\u5e73\u53f0|\u4ea7\u54c1\u540d\u79f0|\u5173\u952e\u8bcd|\u8bbe\u8ba1\u7c7b\u578b|\u662f\u5426\u7206\u6b3e|\u662f\u5426\u4ee3\u53d1|\u5f00\u53d1\u5206\u914d|\u54c1\u724c\u7c7b\u522b|\u5f00\u53d1\u4e3b\u7ba1|\u8bbe\u8ba1\u5206\u914d|\u5f00\u53d1\u5206\u914d\u65f6\u95f4|\u8bbe\u8ba1\u5206\u914d\u65f6\u95f4|\u521b\u5efa\u65f6\u95f4|\u6700\u540e\u4fee\u6539\u65f6\u95f4|\u9879\u76ee\u4fe1\u606f|\u7269\u6599\u6e05\u5355|\u4ea7\u54c1\u4fe1\u606f)/;
    const match = String(text || '').match(new RegExp(escaped + '[:\uff1a]\\s*([\\s\\S]{0,80})'));
    if (!match) return '';
    return compactText(match[1]).split(stop)[0].trim();
  }

  function getProjectLooseField(text, fieldName) {
    const escaped = escapeRegExp(fieldName);
    const stop = /(\u9879\u76ee\u7f16\u7801|\u9700\u6c42\u7f16\u7801|\u5546\u54c1\u540d\u79f0|\u5546\u54c1\u7f16\u7801|\u7f8e\u5de5\u5904\u7406\u4f18\u5148\u7ea7|\u5e73\u53f0|\u4ea7\u54c1\u540d\u79f0|\u5173\u952e\u8bcd|\u8bbe\u8ba1\u7c7b\u578b|\u662f\u5426\u7206\u6b3e|\u662f\u5426\u4ee3\u53d1|\u5f00\u53d1\u5206\u914d|\u54c1\u724c\u7c7b\u522b|\u5f00\u53d1\u4e3b\u7ba1|\u8bbe\u8ba1\u5206\u914d|\u5176\u4ed6\u4fe1\u606f|\u5ba1\u6279\u72b6\u6001|\u9879\u76ee\u72b6\u6001|\u7269\u6599\u6e05\u5355|\u4ea7\u54c1\u4fe1\u606f)/;
    const match = String(text || '').match(new RegExp(escaped + '\\s*[:\uff1a]?\\s*([\\s\\S]{0,120})'));
    if (!match) return '';
    return compactText(match[1]).split(stop)[0].trim();
  }

  function extractDeveloperText(text) {
    const source = compactText(text || '');
    const match = source.match(/\u5f00\u53d1\u4eba\u5458\s*[:\uff1a]?\s*([\s\S]{0,80})/);
    if (!match) return '';
    return compactText(match[1]).split(/\u5f00\u53d1\u4e3b\u7ba1|\u5f00\u53d1\u5efa\u8bae|\u5f00\u53d1\u5206\u914d|\u8bbe\u8ba1\u4eba\u5458|\u9879\u76ee\u8d1f\u8d23\u4eba|\u9879\u76ee\u72b6\u6001/)[0].trim();
  }

  function extractDeveloperName(value) {
    const source = compactText(value || '').replace(/^(?:\u5f00\u53d1\u4eba\u5458|\u5f00\u53d1)\s*[:\uff1a]?\s*/, '').trim();
    if (!source) return '';
    const match = source.match(/^([\u4e00-\u9fa5A-Za-z ._-]+?)(?=\s+(?:\u5f00\u53d1|\u4e3b\u7ba1|\u7ecf\u7406|\u4e13\u5458)|\s*\||$)/);
    return compactText(match ? match[1] : source.split(/[|｜/\\]/)[0]);
  }

  function getMaterialDimensionIssueDeveloper(data) {
    return extractDeveloperName(data && data.developerName)
      || extractDeveloperName(data && data.developerText)
      || extractDeveloperName(data && data.projectOwnerName)
      || '负责人';
  }

  function extractProjectStatus(text) {
    const source = compactText(text || '');
    const statuses = ['\u5f85\u5ba1\u6838', '\u8fdb\u884c\u4e2d', '\u5df2\u62d2\u7edd', '\u5df2\u4f5c\u5e9f', '\u5df2\u5b8c\u6210'];
    const labeled = source.match(/\u9879\u76ee\u72b6\u6001\s*[:\uff1a]?\s*(\u5f85\u5ba1\u6838|\u8fdb\u884c\u4e2d|\u5df2\u62d2\u7edd|\u5df2\u4f5c\u5e9f|\u5df2\u5b8c\u6210)/);
    if (labeled) return labeled[1];
    return statuses.find((status) => source.includes(status)) || '';
  }

  function extractReferenceUrl(text) {
    const match = String(text || '').match(/\u5bf9\u6807\u94fe\u63a5\s*[:\uff1a]?\s*(https?:\/\/[^\s]+)/i);
    return match ? match[1].trim() : '';
  }

  function extractArtPriority(text) {
    const source = compactText(text || '');
    const match = source.match(/\bP[0-9]\s*[-\uff0d]\s*[\u4e00-\u9fa5A-Za-z0-9]{1,8}/);
    return match ? match[0].replace(/\s+/g, '') : '';
  }

  function getMaterialDisplayName(row, keywordPattern) {
    const name = extractMaterialName(row);
    if (!name) return '';
    const match = name.match(keywordPattern);
    return match ? name.slice(match.index).trim() : name.trim();
  }

  // Material names often append the product name after the packaging type.
  // Keep only the recognized packaging kind so unrelated text is not shown as a box remark.
  function getPackageMaterialKind(value) {
    const text = compactText(value);
    const match = text.match(/(纸盒|彩盒|纸箱|包装盒|外盒|印刷自立袋|印刷袋|包装袋|铝箔袋|自封袋|袋子)/);
    return match ? match[1] : '';
  }

  function cleanPackageDisplayLabel(value) {
    const text = compactText(value);
    if (!text) return '';
    const kind = getPackageMaterialKind(text);
    if (!kind) return text;
    return kind + (/多页/.test(text) ? '（多页）' : '');
  }

  function extractMaterialCode(row) {
    const match = String(row || '').match(/\b(MTL\d+)\b/);
    return match ? match[1] : '';
  }

  function getCombinedPrintLabel(rows) {
    const labels = rows.map((row) => cleanPrintLabel(getMaterialDisplayName(row, /(\u6807\u7b7e|\u5370\u5237\u8f6f\u7ba1|\u5370\u5237\u5c3a\u5bf8|\u5370\u5237\u7ba1|\u5370\u5237\u74f6|\u5370\u5237\u4e73\u6db2\u74f6|\u5370\u5237)/) || extractPrintLabelFallback(row))).filter(Boolean);
    return labels.filter((label, index) => labels.indexOf(label) === index).join('\uff1b');
  }

  function extractPrintLabelFallback(row) {
    const match = String(row || '').match(/(\u6807\u7b7e|\u5370\u5237\u8f6f\u7ba1|\u5370\u5237\u5c3a\u5bf8|\u5370\u5237\u7ba1|\u5370\u5237\u74f6|\u5370\u5237\u4e73\u6db2\u74f6|\u5370\u5237)/);
    return match ? match[1] : '';
  }

  function cleanPrintLabel(label) {
    const text = compactText(label);
    if (/\u5370\u5237(?:\u4e73\u6db2\u74f6|\u8f6f\u7ba1|\u7ba1|\u74f6)/.test(text) || (/\u8f6f\u7ba1/.test(text) && /\u5370\u5237/.test(text))) return '\u5370\u5237';
    return text
      .replace(/\uff08\u4ef7\u683c\u5305\u542b\u4e8e\u534a\u6210\u54c1\uff09/g, '')
      .replace(/[\uff08(]\s*\u4ef7\u683c\u5305\u542b[\u5728\u4e8e]\s*\u534a\u6210\u54c1\s*[\uff09)]/g, '')
      .replace(/\uff08\u8fd4\u5de5\s*\u4e00\u6b21\u6027\uff09/g, '')
      .replace(/\uff08\u888b\u542b\u6599\uff09/g, '')
      .trim();
  }

  function extractMaterialName(row) {
    const source = compactText(row || '');
    const match = source.match(/(?:MTL\d+\s+){1,2}(.+?)\s+\u5305\u6750\s*[-\uff0d\u2013\u2014\u2212]/i);
    if (match) return match[1].trim();
    const category = source.match(/\u5305\u6750\s*[-\uff0d\u2013\u2014\u2212]\s*/);
    if (!category) return '';
    const beforeCategory = source.slice(0, category.index).trim();
    const codes = Array.from(beforeCategory.matchAll(/MTL\d+/gi));
    if (!codes.length) return '';
    const lastCode = codes[codes.length - 1];
    return beforeCategory.slice((lastCode.index || 0) + lastCode[0].length).trim();
  }

  function extractNamedDimensionStrings(text) {
    const source = String(text || '');
    if (isTubePrintRow(source)) {
      const tubeDim = extractPrintDimensionString(source);
      return tubeDim ? [tubeDim] : [];
    }
    const axisDim = extractAxisDimensionString(source);
    const pattern = /(?:([\u4e00-\u9fa5A-Za-z0-9锛堬級()_-]{1,16})[:\uff1a]\s*)?(\d+(?:\.\d+)?\s*[xX\u00d7*]\s*\d+(?:\.\d+)?(?:\s*[xX\u00d7*]\s*\d+(?:\.\d+)?){0,4}\s*(?:cm|mm))/ig;
    const items = [];
    if (axisDim) items.push(axisDim);
    let match;
    while ((match = pattern.exec(source))) {
      let name = match[1] ? match[1].trim() : '';
      if (!name) {
        const before = source.slice(Math.max(0, match.index - 12), match.index);
        const implicit = before.match(/([\u4e00-\u9fa5A-Za-z0-9锛堬級()_-]{1,8})$/);
        name = implicit ? implicit[1].trim() : '';
      }
      const dim = normalizeDimensionText(match[2]);
      if (!dim) continue;
      if (items.includes(dim)) continue;
      items.push(name && !isGenericDimensionName(name) ? name + '\uff1a' + dim : dim);
    }
    return items;
  }

  function hasPrintDimensionText(text) {
    const source = String(text || '');
    return /\d+(?:\.\d+)?\s*[xX\u00d7*]\s*\d+(?:\.\d+)?(?:\s*[xX\u00d7*]\s*\d+(?:\.\d+)?){0,4}\s*(?:cm|mm)/i.test(source)
      || !!extractAxisDimensionString(source)
      || !!detectMaterialDimensionUnitIssue(source);
  }

  function extractPrintDimensionString(text) {
    const source = String(text || '');
    const axisDim = extractAxisDimensionString(source);
    if (axisDim) return axisDim;
    const match = source.match(/\u5370\u5237(?:\u5c3a\u5bf8)?[^\d]{0,12}(\d+(?:\.\d+)?\s*[xX\u00d7*]\s*\d+(?:\.\d+)?(?:\s*[xX\u00d7*]\s*\d+(?:\.\d+)?){0,4}\s*(?:cm|mm))/i);
    return match ? normalizeDimensionText(match[1]) : '';
  }

  function extractAxisDimensionString(text) {
    const source = String(text || '');
    const match = source.match(/\u5370\u5237(?:\u5c3a\u5bf8)?[^\d]{0,12}(?:\u957f|\u5bbd|\u9ad8)?\s*(\d+(?:\.\d+)?)\s*(cm|mm)?\s*(?:[xX\u00d7*]\s*)?(?:\u957f|\u5bbd|\u9ad8)\s*(\d+(?:\.\d+)?)\s*(cm|mm)/i);
    if (!match) return '';
    const unit = (match[4] || match[2] || 'cm').toLowerCase();
    return normalizeDimensionParts([match[1], match[3]], unit);
  }

  function isGenericDimensionName(name) {
    return /^(?:\u5370\u5237|\u6807\u7b7e|\u5370\u5237\u5c3a\u5bf8|\u6807\u7b7e\u5c3a\u5bf8|\u5c3a\u5bf8)$/.test(String(name || '').trim());
  }

  function isTubePrintRow(row) {
    const text = String(row || '');
    return /\u5370\u5237(?:\u8f6f\u7ba1|\u7ba1|\u74f6|\u4e73\u6db2\u74f6)/.test(text) || (hasStrongTubeMaterialFeatures(text) && /\u5370\u5237(?:\u5c3a\u5bf8)?/.test(text));
  }

  function hasStrongTubeMaterialFeatures(text) {
    const source = String(text || '');
    if (/\u8f6f\u7ba1|\u767d\u7ba1|\u9ed1\u7ba1|(?:PE|pe)[^\s,，;；]{0,4}\u7ba1/.test(source)) return true;
    const structuralMarkers = ['\u7ba1\u5f84', '\u7ba1\u8eab', '\u5c01\u5c3e', '\u76d6\u5b50\u9ad8\u5ea6', '\u603b\u9ad8\u5ea6'].filter((marker) => source.includes(marker));
    return structuralMarkers.length >= 2;
  }

  function isTubePrintData(data) {
    // The segmented size is the authoritative signal for tube-specific fields.
    // Material labels alone are not enough: printed bags and other print materials
    // can contain the same words but must not show a tail-seal length.
    return Boolean(String(data && data.tubeSegmentText || '').trim());
  }

  function findTubeSizeSpec(text, fields) {
    const diameter = fields && fields.diameter ? fields.diameter : 0;
    const body = fields && fields.body ? fields.body : 0;
    if (!diameter || !body) return null;
    let spec = diameter && body ? TUBE_SIZE_SPECS.find((item) => item.diameter === diameter && item.body === body) : null;
    let rule = null;
    if (!spec && diameter && body) {
      rule = TUBE_SIZE_RULES.find((item) => item.diameter === diameter && item.bodies.includes(body));
      if (rule) spec = buildTubeSpecFromRule(rule, body);
    }
    if (!spec) return null;
    const tailSeal = (Number(spec.widths[1]) || 0) + (Number(spec.widths[2]) || 0);
    return {
      diameter,
      body,
      key: spec.key || (diameter + '\u7ba1\u5f84' + body + '\u7ba1\u8eab'),
      widths: spec.widths.slice(),
      printSizeText: formatTubeSpecPrintSize(spec),
      segmentText: spec.widths.map(formatCmSegment).join('-') + 'cm',
      tailSealText: formatSingleDimension(tailSeal),
    };
  }

  function buildTubeSpecFromRule(rule, body) {
    const size = getTubeRulePrintSize(rule, body);
    return {
      key: rule.diameter + '\u7ba1\u5f84' + body + '\u7ba1\u8eab',
      diameter: rule.diameter,
      body,
      widths: rule.widths.slice(),
      width: size.width,
      height: size.height,
    };
  }

  function extractTubeFields(root) {
    if (!root) return { diameter: 0, body: 0, text: '' };
    const fullText = getVisibleText(root);
    const diameter = normalizeTubeMeasureText(getFormValueByLooseLabel('\u7ba1\u5f84', root)) || extractTubeMeasure(fullText, '\u7ba1\u5f84');
    const body = normalizeTubeMeasureText(getFormValueByLooseLabel('\u7ba1\u8eab', root)) || extractTubeMeasure(fullText, '\u7ba1\u8eab');
    const parts = [];
    if (diameter) parts.push('\u7ba1\u5f84 ' + diameter + 'mm');
    if (body) parts.push('\u7ba1\u8eab ' + body + 'mm');
    return { diameter, body, text: parts.join(' ') };
  }

  function extractTubePrintDimensionNums(text) {
    const source = String(text || '');
    const labeled = source.match(/\u5370\u5237(?:\u5c3a\u5bf8)?[^\d]{0,20}(\d+(?:\.\d+)?)\s*[xX\u00d7*]\s*(\d+(?:\.\d+)?)\s*(mm|cm)/i);
    if (labeled) {
      const unit = labeled[3].toLowerCase();
      return [normalizeDimensionUnitNumber(labeled[1], unit), normalizeDimensionUnitNumber(labeled[2], unit)];
    }
    const dimension = source.match(/(\d+(?:\.\d+)?)\s*[xX\u00d7*]\s*(\d+(?:\.\d+)?)\s*(mm|cm)/i);
    if (!dimension) return null;
    const unit = dimension[3].toLowerCase();
    return [normalizeDimensionUnitNumber(dimension[1], unit), normalizeDimensionUnitNumber(dimension[2], unit)];
  }

  function getTubeRulePrintSize(rule, body) {
    const width = rule.widths.reduce((sum, value) => sum + (Number(value) || 0), 0);
    const height = Math.max(0, (Number(body) || 0) / 10 - 0.1);
    return { width, height };
  }

  function formatTubeSpecPrintSize(spec) {
    if (!spec || !Number.isFinite(Number(spec.width)) || !Number.isFinite(Number(spec.height))) return '';
    return trimNumber(Number(spec.width)) + 'x' + trimNumber(Number(spec.height)) + 'cm';
  }

  function normalizeDimensionUnitNumber(value, unit) {
    const num = Number(value);
    if (!Number.isFinite(num)) return 0;
    return String(unit || '').toLowerCase() === 'mm' ? num / 10 : num;
  }

  function extractTubeMeasure(text, label) {
    const source = String(text || '');
    const escaped = escapeRegExp(label);
    const labelPair = source.match(/\u7ba1\u5f84\s+\u7ba1\u8eab\s+(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)/i);
    if (labelPair) return normalizeTubeMeasureValue(label === '\u7ba1\u5f84' ? labelPair[1] : labelPair[2], '');
    const inlinePair = source.match(/\u7ba1\u5f84[^\d]{0,12}(\d+(?:\.\d+)?)\s*(mm|cm)?[^\u7ba1\d]{0,20}\u7ba1\u8eab[^\d]{0,12}(\d+(?:\.\d+)?)\s*(mm|cm)?/i);
    if (inlinePair) {
      const diameterUnit = inlinePair[2] || inlinePair[4] || '';
      const bodyUnit = inlinePair[4] || inlinePair[2] || '';
      return label === '\u7ba1\u5f84'
        ? normalizeTubeMeasureValue(inlinePair[1], diameterUnit)
        : normalizeTubeMeasureValue(inlinePair[3], bodyUnit);
    }
    const labelIndex = source.search(new RegExp(escaped, 'i'));
    const scope = labelIndex >= 0 ? source.slice(labelIndex, labelIndex + 120) : source;
    const direct = scope.match(new RegExp(escaped + '[^\\d]{0,24}(\\d+(?:\\.\\d+)?)\\s*(mm|cm)?', 'i'));
    if (direct) return normalizeTubeMeasureValue(direct[1], direct[2]);
    const tableLike = scope.match(/(\d+(?:\.\d+)?)\s*(mm|cm)/i);
    if (tableLike) return normalizeTubeMeasureValue(tableLike[1], tableLike[2]);
    return 0;
  }

  function normalizeTubeMeasureText(text) {
    const match = String(text || '').match(/(\d+(?:\.\d+)?)\s*(mm|cm)?/i);
    return match ? normalizeTubeMeasureValue(match[1], match[2]) : 0;
  }

  function normalizeTubeMeasureValue(value, unit) {
    const num = Number(value);
    if (!Number.isFinite(num) || num <= 0) return 0;
    const normalized = String(unit || '').toLowerCase() === 'cm' ? num * 10 : num;
    return Math.round(normalized);
  }

  function formatCmSegment(value) {
    const number = Number(value);
    if (!Number.isFinite(number)) return '';
    const text = String(number);
    return text.includes('.') ? text : text + '.0';
  }

  function getMaterialRows(root) {
    return Array.from(root.querySelectorAll('tr, .ant-table-row, [role="row"]'))
      .filter(isVisibleElement)
      .map((el) => compactText(el.innerText || el.textContent || ''))
      .flatMap(splitCombinedMaterialRow)
      .filter((text, idx, arr) => text && arr.indexOf(text) === idx);
  }

  function splitCombinedMaterialRow(text) {
    const source = String(text || '');
    const matches = Array.from(source.matchAll(/\bMTL\d+\b/gi));
    if (matches.length < 2) return [source];
    const starts = [];
    let previousCode = '';
    matches.forEach((match) => {
      const code = String(match[0] || '').toUpperCase();
      if (code !== previousCode) starts.push(Number(match.index) || 0);
      previousCode = code;
    });
    if (starts.length < 2) return [source];
    return starts.map((start, index) => source.slice(start, starts[index + 1] || source.length).trim()).filter(Boolean);
  }

  function extractNetContentFromMaterial(row) {
    const tabletMatch = String(row || '').match(/(\d+(?:\.\d+)?)\s*\u7247\s*(?:\/\s*(?:\u76d2|\u74f6|\u888b))?/i);
    if (tabletMatch) return trimNumber(Number(tabletMatch[1])) + 'TABLETS';
    const pcsMatch = String(row || '').match(/(\d+(?:\.\d+)?)\s*(PCS?)\s*(?:\/\s*(?:\u4ef6|\u76d2|\u74f6|\u888b))?/i);
    if (pcsMatch) return trimNumber(Number(pcsMatch[1])) + pcsMatch[2].toUpperCase();
    const pairMatch = String(row || '').match(/(\d+(?:\.\d+)?)\s*\u5957\s*\/\s*\u76d2/i);
    if (pairMatch) {
      const count = Number(pairMatch[1]);
      return trimNumber(count) + (count === 1 ? 'PAIR' : 'PAIRS');
    }
    const match = String(row || '').match(/(\d+(?:\.\d+)?)\s*(g|kg|ml|mL|l|L|\u514b|\u5343\u514b|\u6beb\u5347|\u5347)\s*\/\s*\u76d2/i);
    if (!match) return '';
    const unitMap = {
      '\u514b': 'g',
      '\u5343\u514b': 'kg',
      '\u6beb\u5347': 'ml',
      '\u5347': 'L',
    };
    const unit = unitMap[match[2]] || match[2];
    return trimNumber(Number(match[1])) + unit;
  }

  function extractDimensionString(text) {
    const matches = String(text || '').match(/\d+(?:\.\d+)?(?:\s*[xX\u00d7*]\s*\d+(?:\.\d+)?\s*(?:(?:cm|mm))?){1,4}\s*(?:cm|mm)/ig);
    if (!matches || !matches.length) return '';
    return normalizeDimensionText(matches[matches.length - 1]);
  }

  function normalizeDimensionText(text) {
    const source = String(text || '');
    const nums = source.match(/\d+(?:\.\d+)?/g);
    if (!nums || nums.length < 2) return '';
    const unitMatch = source.match(/(mm|cm)\s*$/i) || source.match(/\b(mm|cm)\b/i);
    return normalizeDimensionParts(nums, unitMatch ? unitMatch[1] : 'cm');
  }

  function normalizeDimensionParts(nums, unit) {
    const divisor = String(unit || '').toLowerCase() === 'mm' ? 10 : 1;
    return nums.map((n) => trimNumber(Number(n) / divisor)).join('x') + 'cm';
  }

  function detectMaterialDimensionUnitIssue(text) {
    const source = String(text || '');
    const match = source.match(/(\d+(?:\.\d+)?(?:\s*[xX\u00d7*]\s*\d+(?:\.\d+)?){1,4}\s*m(?!m|l))/i);
    if (match) return { unit: 'm', raw: compactText(match[1]) };
    const meterMatches = Array.from(source.matchAll(/\d+(?:\.\d+)?\s*m(?!m|l)/ig));
    if (meterMatches.length >= 2) {
      const start = Number(meterMatches[0].index) || 0;
      const end = (Number(meterMatches[meterMatches.length - 1].index) || start) + meterMatches[meterMatches.length - 1][0].length;
      return { unit: 'm', raw: compactText(source.slice(start, end)) };
    }
    return null;
  }

  function normalizeMaterialDimensionUnitIssue(value) {
    if (!value) return null;
    if (typeof value === 'string') return detectMaterialDimensionUnitIssue(value);
    if (String(value.unit || '').toLowerCase() !== 'm') return null;
    const raw = compactText(value.raw || '');
    return { unit: 'm', raw: raw || 'm' };
  }

  function normalizeMaterialDimensionUnitIssues(value, data) {
    const source = value && typeof value === 'object' ? value : {};
    return {
      package: normalizeMaterialDimensionUnitIssue(source.package) || detectMaterialDimensionUnitIssue(data && data.packageSizeText),
      print: normalizeMaterialDimensionUnitIssue(source.print) || detectMaterialDimensionUnitIssue(data && data.printSizeText),
    };
  }

  function getMaterialDimensionUnitIssue(data, kind) {
    const issues = normalizeMaterialDimensionUnitIssues(data && data.materialDimensionUnitIssues, data);
    return issues[kind] || null;
  }

  function extractOuterPackage(root) {
    const nums = [
      getFormValueByLabel('\u957f\uff08\u5916\u5305\u88c5\uff09', root),
      getFormValueByLabel('\u5bbd\uff08\u5916\u5305\u88c5\uff09', root),
      getFormValueByLabel('\u9ad8\uff08\u5916\u5305\u88c5\uff09', root),
    ].map(firstNumber);
    return nums.every((n) => Number.isFinite(n)) ? { packageNums: nums } : { packageNums: null };
  }

  function getPackageMaterialRowScore(row) {
    const text = String(row || '');
    if (!/\u5305\u6750/.test(text)) return 0;
    const name = extractMaterialName(text);
    const bagPattern = /(\u5370\u5237\u81ea\u7acb\u888b|\u5370\u5237\u888b|\u5305\u88c5\u888b|\u94dd\u7b94\u888b|\u81ea\u5c01\u888b|\u888b\u5b50)/;
    let score = 0;
    if (/\u7eb8\u76d2/.test(name)) score += 140;
    else if (bagPattern.test(name)) score += 120;
    if (/\u5305\u6750\s*-\s*\u7eb8\u76d2/.test(text)) score += 80;
    else if (new RegExp('\\u5305\\u6750\\s*-\\s*[^;]{0,36}' + bagPattern.source).test(text)) score += 35;
    if (/\u767d\u5361|\u9ed1\u5361|\u725b\u76ae\u7eb8|\u74e6\u695e/.test(text)) score += 10;
    if (/\u74f6|\u65cb\u76d6|\u6cf5\u5934|\u55b7\u5934|\u7f50|\u8f6f\u7ba1|\u6ef4\u7ba1|\u5237\u5934|\u76d6\u5b50/.test(name)) score -= 180;
    return score;
  }

  function extractInnerPackage(root) {
    const labelGroups = [
      ['\u957f（\u5185\u5305\u6750）', '\u957f（\u4ea7\u54c1）'],
      ['\u5bbd（\u5185\u5305\u6750）', '\u5bbd（\u4ea7\u54c1）'],
      ['\u9ad8（\u5185\u5305\u6750）', '\u9ad8（\u4ea7\u54c1）'],
    ];
    const nums = labelGroups.map((labels) => {
      const value = labels.map((label) => getFormValueByLabel(label, root)).find(Boolean) || '';
      return firstNumber(value);
    });
    return nums.every((value) => Number.isFinite(value) && value > 0) ? { productNums: nums } : { productNums: null };
  }

  function emptyPackaging() {
    return { packageSizeText: '', packageSizeLabel: '', packageCode: '', packageNums: null, hasInnerCard: false, printSizeText: '', printSizeLabel: '', printCode: '', materialDimensionUnitIssues: { package: null, print: null }, netContent: '' };
  }

  function extractFoodSemiFinished(root) {
    const row = getMaterialRows(root).find((text) => /\u534a\u6210\u54c1/.test(text) && /\u98df\u54c1\u7c7b/.test(text) && /(\u80f6\u56ca|\u8f6f\u7cd6)/.test(text)) || '';
    if (!row) return emptyFoodSemiFinished();
    const dim = extractDimensionString(row);
    const nums = parseDimension(dim, 2);
    const productNums = nums && nums.length >= 2 ? [nums[0], nums[0], nums[1]] : null;
    const count = (row.match(/(\d+(?:\.\d+)?)\s*\u7c92/) || [])[1];
    const type = /\u8f6f\u7cd6/.test(row) ? 'GUMMIES' : 'CAPSULES';
    return {
      productNums,
      netContent: count ? trimNumber(Number(count)) + type : '',
    };
  }

  function emptyFoodSemiFinished() {
    return { productNums: null, netContent: '' };
  }

  function getBestNetContent(root) {
    return extractSpecModelNetContent(root);
  }

  function normalizeNetContentValue(value) {
    const text = compactText(value);
    if (!text) return '';
    const pcMatch = text.match(/(\d+(?:\.\d+)?)\s*(PCS?)\s*(?:\/\s*(?:\u4ef6|\u76d2|\u74f6|\u888b))?/i);
    if (pcMatch) return trimNumber(Number(pcMatch[1])) + pcMatch[2].toUpperCase();
    if (/^\d+(?:\.\d+)?\s*(CAPSULES|GUMMIES|TABLETS|PAIR|PAIRS|PC)$/i.test(text)) return text.replace(/\s+/g, '').toUpperCase();
    const capsuleMatch = text.match(/(\d+(?:\.\d+)?)\s*(?:\u7c92|\u80f6\u56ca)\s*(?:\/\s*(?:\u76d2|\u74f6|\u888b))?/i);
    if (capsuleMatch) return trimNumber(Number(capsuleMatch[1])) + 'CAPSULES';
    const tabletMatch = text.match(/(\d+(?:\.\d+)?)\s*\u7247\s*(?:\/\s*(?:\u76d2|\u74f6|\u888b))?/i);
    if (tabletMatch) return trimNumber(Number(tabletMatch[1])) + 'TABLETS';
    const weightMatch = text.match(/(\d+(?:\.\d+)?)\s*(kg|g|ml|l|\u514b|\u5343\u514b|\u6beb\u5347|\u5347)\s*(?:\/\s*[\u4e00-\u9fa5A-Za-z]+)?/i);
    if (weightMatch) {
      return formatNetContentAmount(weightMatch[1], weightMatch[2]);
    }
    return '';
  }

  function extractSpecModelNetContent(root) {
    const lines = getVisibleText(root).split('\n').map((line) => compactText(line)).filter(Boolean);
    for (let i = 0; i < lines.length; i += 1) {
      if (!/\u89c4\u683c\u578b\u53f7/.test(lines[i])) continue;
      const sameLine = lines[i].replace(/\u89c4\u683c\u578b\u53f7[:\uff1a]?/, '').trim();
      const candidates = [sameLine, lines[i + 1] || ''].filter(Boolean);
      for (const candidate of candidates) {
        const normalized = normalizeNetContentValue(candidate);
        if (normalized) return normalized;
      }
    }
    return '';
  }

  function formatNetContentAmount(amount, unitRaw) {
    const unitMap = { '\u514b': 'g', '\u5343\u514b': 'kg', '\u6beb\u5347': 'ml', '\u5347': 'L' };
    return trimNumber(Number(amount)) + (unitMap[unitRaw] || unitRaw);
  }

  function productNumsFromPackage(packageNums, hasInnerCard) {
    if (!Array.isArray(packageNums) || packageNums.length < 3) return null;
    const delta = hasInnerCard ? INNER_CARD_DELTA_CM : NORMAL_DELTA_CM;
    return packageNums.slice(0, 3).map((n) => Math.max(0, n - delta));
  }

  function formatDimensionPart(nums, index) {
    if (!Array.isArray(nums) || !Number.isFinite(nums[index])) return '';
    return formatSingleDimension(nums[index]);
  }

  function formatSingleDimension(value) {
    if (!Number.isFinite(Number(value))) return '';
    const cm = trimNumber(Number(value));
    const inch = trimNumber(Number(value) * CM_TO_INCH);
    return cm + 'cm/' + inch + 'inch';
  }

  function getFormValueByLabel(fieldLabel, root) {
    const labels = Array.from(root.querySelectorAll('label, .ant-form-item-label, .ant-descriptions-item-label, [class*="label"], [class*="Label"]'))
      .filter(isVisibleElement)
      .filter((el) => normalizeFieldLabel(el.textContent) === fieldLabel);
    for (const labelEl of labels) {
      const item = labelEl.closest('.ant-form-item') || labelEl.parentElement;
      if (!item || !isVisibleElement(item)) continue;
      const controlValue = getVisibleFormControlValue(item);
      if (controlValue) return controlValue;
      const text = compactText(item.innerText || item.textContent || '');
      const value = text.replace(new RegExp('^' + escapeRegExp(fieldLabel) + '\\*?\\s*'), '').trim();
      const cleaned = cleanValue(value);
      if (cleaned) return cleaned;
    }
    return '';
  }

  function getFormValueByLooseLabel(fieldLabel, root) {
    const expected = normalizeLooseFieldLabel(fieldLabel);
    const labels = Array.from(root.querySelectorAll('label, .ant-form-item-label, .ant-descriptions-item-label, [class*="label"], [class*="Label"]'))
      .filter(isVisibleElement)
      .filter((el) => normalizeLooseFieldLabel(el.textContent) === expected);
    for (const labelEl of labels) {
      const item = labelEl.closest('.ant-form-item') || labelEl.closest('.ant-descriptions-item') || labelEl.parentElement;
      if (!item || !isVisibleElement(item)) continue;
      const controlValue = getVisibleFormControlValue(item);
      if (controlValue) return controlValue;
      const text = compactText(item.innerText || item.textContent || '');
      const value = text
        .replace(new RegExp('^' + escapeRegExp(normalizeFieldLabel(labelEl.textContent)) + '\\*?\\s*'), '')
        .replace(new RegExp('^' + escapeRegExp(fieldLabel) + '(?:\\s*[\\uff08(][^\\uff09)]*[\\uff09)])?\\*?\\s*'), '')
        .trim();
      const cleaned = cleanValue(value);
      if (cleaned) return cleaned;
    }
    return getFormValueByLabel(fieldLabel, root);
  }

  function getVisibleFormControlValue(item) {
    if (!item) return '';
    const control = Array.from(item.querySelectorAll('input, textarea, select'))
      .filter(isVisibleElement)
      .find((element) => cleanValue(element.value || element.getAttribute('value') || ''));
    if (control) return cleanValue(control.value || control.getAttribute('value') || '');
    const valueNode = Array.from(item.querySelectorAll('.ant-select-selection-item, .ant-input-number-input, .ant-descriptions-item-content'))
      .filter(isVisibleElement)
      .find((element) => cleanValue(element.innerText || element.textContent || ''));
    return valueNode ? cleanValue(valueNode.innerText || valueNode.textContent || '') : '';
  }

  function normalizeLooseFieldLabel(text) {
    return normalizeFieldLabel(text)
      .replace(/\*?(?:\u70b9\u51fb)?\u67e5\u770b\u98ce\u9669$/g, '')
      .replace(/[\uff08(]\s*(?:mm|cm|kg|g|ml|l|\u6beb\u7c73|\u5398\u7c73|\u5343\u514b|\u514b|\u6beb\u5347|\u5347)\s*[\uff09)]/ig, '')
      .replace(/\s+/g, '')
      .trim();
  }

  function normalizeWeight(raw) {
    if (!raw) return '';
    const match = String(raw).match(/(\d+(?:\.\d+)?)\s*(kg|\u5343\u514b|g|\u514b)/i);
    if (!match) return cleanValue(raw);
    const unit = /kg|\u5343\u514b/i.test(match[2]) ? 'kg' : 'g';
    return trimNumber(Number(match[1])) + unit;
  }

  function getGrossWeightValue(root) {
    const raw = getFormValueByLooseLabel('\u6bdb\u91cd', root);
    if (!raw) return '';
    if (/(?:kg|\u5343\u514b|g|\u514b)/i.test(raw)) return normalizeWeight(raw);
    if (/^\d+(?:\.\d+)?$/.test(raw)) {
      const label = Array.from(root.querySelectorAll('label, .ant-form-item-label, .ant-descriptions-item-label, [class*="label"], [class*="Label"]'))
        .filter(isVisibleElement)
        .find((element) => normalizeLooseFieldLabel(element.textContent) === '\u6bdb\u91cd');
      const unitText = String(label && label.textContent || '');
      if (/(?:kg|\u5343\u514b)/i.test(unitText)) return normalizeWeight(raw + 'kg');
      if (/(?:g|\u514b)/i.test(unitText)) return normalizeWeight(raw + 'g');
    }
    return normalizeWeight(raw);
  }

  function cleanValue(value) {
    const text = compactText(value);
    if (!text || text === '--' || /^--\s*(g|kg|ml|mL|l|L|\u514b|\u5343\u514b|\u6beb\u5347|\u5347|\w*\([^)]*\))?/i.test(text)) return '';
    if (/^[\s:：*]*(\u51c0\u542b\u91cf|\u51c0\u91cd|\u6bdb\u91cd|\u89c4\u683c\u578b\u53f7|\u5bb9\u91cf)(\s+|\u3000)*(\u51c0\u542b\u91cf|\u51c0\u91cd|\u6bdb\u91cd|\u89c4\u683c\u578b\u53f7|\u5bb9\u91cf)?[\s:：*]*$/.test(text)) return '';
    return text;
  }

  function parseDimension(text, limit) {
    const nums = String(text || '').match(/\d+(?:\.\d+)?/g);
    if (!nums || nums.length < limit) return null;
    return nums.map(Number);
  }

  function appendChineseRemark(label, remark) {
    const base = label || L.packageSize;
    return new RegExp('\uff08' + escapeRegExp(remark) + '\uff09').test(base) ? base : base + '\uff08' + remark + '\uff09';
  }

  function firstNumber(text) {
    const match = String(text || '').match(/\d+(?:\.\d+)?/);
    return match ? Number(match[0]) : NaN;
  }

  function findSku(text) {
    return (text.match(/\u5546\u54c1\u7f16\u7801[:\uff1a]\s*(SKU\d+)/i) || text.match(/\b(SKU\d+)\b/i) || [])[1] || '';
  }

  function cleanName(name) {
    return compactText(name)
      .replace(/\s*(\u5546\u54c1\u7f16\u7801|\u7f8e\u5de5\u5904\u7406\u4f18\u5148\u7ea7|PRODUCT NAME)[:\uff1a].*$/i, '')
      .replace(/\s*[\uff08(]\d+[\uff09)]\s*$/g, '')
      .trim();
  }

  function normalizeProductNameValue(value) {
    const text = compactText(value);
    if (!text || /^(?:--+|—+|－+|未填写|未命名|预设编码新品)$/i.test(text)) return '';
    return text;
  }

  function findTabButton(root, text) {
    const candidates = Array.from(root.querySelectorAll('[role="tab"], .ant-tabs-tab, .ant-tabs-tab-btn, button, div'))
      .filter(isVisibleElement)
      .filter((el) => {
        const current = compactText(el.textContent);
        return current === text || current.startsWith(text + ' ');
      });
    return candidates.find((el) => el.getAttribute('role') === 'tab')
      || candidates.find((el) => String(el.className || '').includes('ant-tabs-tab-btn'))
      || candidates[0]
      || null;
  }

  function getActiveTabText(root) {
    const active = Array.from(root.querySelectorAll('[role="tab"], .ant-tabs-tab'))
      .filter(isVisibleElement)
      .find(isActiveTab);
    return active ? compactText(active.textContent) : '';
  }

  function isActiveTab(tab) {
    const tabRoot = tab.closest('.ant-tabs-tab') || tab;
    return /\bant-tabs-tab-active\b/.test(String(tabRoot.className || ''))
      || tab.getAttribute('aria-selected') === 'true';
  }

